module.exports = [{"id":"han_001","title":"长歌行","author":"汉乐府","dynasty":"两汉","dynastyCode":"han","content":"青青园中葵，朝露待日晞。\n阳春布德泽，万物生光辉。\n常恐秋节至，焜黄华叶衰。\n百川东到海，何时复西归？\n少壮不努力，老大徒伤悲。","tags":["乐府","劝学","哲理","小学必背"]},{"id":"han_002","title":"短歌行","author":"曹操","dynasty":"两汉","dynastyCode":"han","content":"对酒当歌，人生几何！\n譬如朝露，去日苦多。\n慨当以慷，忧思难忘。\n何以解忧？唯有杜康。\n青青子衿，悠悠我心。\n但为君故，沉吟至今。\n呦呦鹿鸣，食野之苹。\n我有嘉宾，鼓瑟吹笙。\n明明如月，何时可掇？\n忧从中来，不可断绝。\n越陌度阡，枉用相存。\n契阔谈讌，心念旧恩。\n月明星稀，乌鹊南飞。\n绕树三匝，何枝可依？\n山不厌高，海不厌深。\n周公吐哺，天下归心。","tags":["乐府","求贤","名篇","高中必背"]},{"id":"han_003","title":"观沧海","author":"曹操","dynasty":"两汉","dynastyCode":"han","content":"东临碣石，以观沧海。\n水何澹澹，山岛竦峙。\n树木丛生，百草丰茂。\n秋风萧瑟，洪波涌起。\n日月之行，若出其中。\n星汉灿烂，若出其里。\n幸甚至哉，歌以咏志。","tags":["乐府","写景","豪放","初中必背"]},{"id":"han_004","title":"龟虽寿","author":"曹操","dynasty":"两汉","dynastyCode":"han","content":"神龟虽寿，犹有竟时。\n腾蛇乘雾，终为土灰。\n老骥伏枥，志在千里。\n烈士暮年，壮心不已。\n盈缩之期，不但在天。\n养怡之福，可得永年。\n幸甚至哉，歌以咏志。","tags":["乐府","哲理","名篇","初中必背"]},{"id":"han_005","title":"陌上桑","author":"汉乐府","dynasty":"两汉","dynastyCode":"han","content":"日出东南隅，照我秦氏楼。秦氏有好女，自名为罗敷。\n罗敷喜蚕桑，采桑城南隅。青丝为笼系，桂枝为笼钩。\n头上倭堕髻，耳中明月珠。缃绮为下裙，紫绮为上襦。\n行者见罗敷，下担捋髭须。少年见罗敷，脱帽著帩头。\n耕者忘其犁，锄者忘其锄。来归相怨怒，但坐观罗敷。\n使君从南来，五马立踟蹰。使君遣吏往，问是谁家姝？\n秦氏有好女，自名为罗敷。罗敷年几何？二十尚不足，十五颇有余。\n使君谢罗敷：宁可共载不？罗敷前致辞：使君一何愚！\n使君自有妇，罗敷自有夫。","tags":["乐府","叙事","名篇"]},{"id":"han_006","title":"孔雀东南飞（节选）","author":"佚名","dynasty":"两汉","dynastyCode":"han","content":"孔雀东南飞，五里一徘徊。\n十三能织素，十四学裁衣。\n十五弹箜篌，十六诵诗书。\n十七为君妇，心中常苦悲。\n君既为府吏，守节情不移。\n贱妾留空房，相见常日稀。\n鸡鸣入机织，夜夜不得息。\n三日断五匹，大人故嫌迟。\n非为织作迟，君家妇难为。","tags":["乐府","叙事","名篇","高中必背"]},{"id":"han_007","title":"古诗十九首·行行重行行","author":"佚名","dynasty":"两汉","dynastyCode":"han","content":"行行重行行，与君生别离。\n相去万余里，各在天一涯。\n道路阻且长，会面安可知？\n胡马依北风，越鸟巢南枝。\n相去日已远，衣带日已缓。\n浮云蔽白日，游子不顾返。\n思君令人老，岁月忽已晚。\n弃捐勿复道，努力加餐饭。","tags":["古诗十九首","思乡","名篇","高中必背"]},{"id":"han_008","title":"古诗十九首·迢迢牵牛星","author":"佚名","dynasty":"两汉","dynastyCode":"han","content":"迢迢牵牛星，皎皎河汉女。\n纤纤擢素手，札札弄机杼。\n终日不成章，泣涕零如雨。\n河汉清且浅，相去复几许。\n盈盈一水间，脉脉不得语。","tags":["古诗十九首","爱情","名篇","初中必背"]},{"id":"han_009","title":"古诗十九首·涉江采芙蓉","author":"佚名","dynasty":"两汉","dynastyCode":"han","content":"涉江采芙蓉，兰泽多芳草。\n采之欲遗谁，所思在远道。\n还顾望旧乡，长路漫浩浩。\n同心而离居，忧伤以终老。","tags":["古诗十九首","思乡","名篇"]},{"id":"han_010","title":"十五从军征","author":"汉乐府","dynasty":"两汉","dynastyCode":"han","content":"十五从军征，八十始得归。\n道逢乡里人：家中有阿谁？\n遥看是君家，松柏冢累累。\n兔从狗窦入，雉从梁上飞。\n中庭生旅谷，井上生旅葵。\n舂谷持作饭，采葵持作羹。\n羹饭一时熟，不知饴阿谁。\n出门东向看，泪落沾我衣。","tags":["乐府","战争","名篇","初中必背"]},{"id":"han_011","title":"四愁诗","author":"张衡","dynasty":"两汉","dynastyCode":"han","content":"我所思兮在太山，欲往从之梁父艰。侧身东望涕沾翰。美人赠我金错刀，何以报之英琼瑶。路远莫致倚逍遥，何为怀忧心烦劳。","tags":["七言诗","抒情","名篇"]},{"id":"han_012","title":"赠从弟","author":"刘桢","dynasty":"两汉","dynastyCode":"han","content":"亭亭山上松，瑟瑟谷中风。风声一何盛，松枝一何劲。冰霜正惨凄，终岁常端正。岂不罹凝寒，松柏有本性。","tags":["五言诗","咏物","名篇"]},{"id":"han_013","title":"悲愤诗","author":"蔡琰","dynasty":"两汉","dynastyCode":"han","content":"汉季失权柄，董卓乱天常。志欲图篡弑，先害诸贤良。逼迫迁旧邦，拥主以自强。海内兴义师，欲共讨不祥。","tags":["五言诗","叙事","名篇"]},{"id":"han_014","title":"江南","author":"汉乐府","dynasty":"两汉","dynastyCode":"han","content":"江南可采莲，莲叶何田田。鱼戏莲叶间。鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北。","tags":["乐府","民歌","小学必背"]},{"id":"ming_001","title":"石灰吟","author":"于谦","dynasty":"明","dynastyCode":"ming","content":"千锤万凿出深山，烈火焚烧若等闲。粉骨碎身浑不怕，要留清白在人间。","tags":["咏物","言志","小学必背"]},{"id":"ming_002","title":"临江仙·滚滚长江东逝水","author":"杨慎","dynasty":"明","dynastyCode":"ming","content":"滚滚长江东逝水，浪花淘尽英雄。是非成败转头空。青山依旧在，几度夕阳红。白发渔樵江渚上，惯看秋月春风。一壶浊酒喜相逢。古今多少事，都付笑谈中。","tags":["明词","怀古","名篇"]},{"id":"ming_003","title":"明日歌","author":"钱福","dynasty":"明","dynastyCode":"ming","content":"明日复明日，明日何其多。我生待明日，万事成蹉跎。世人若被明日累，春去秋来老将至。朝看水东流，暮看日西坠。百年明日能几何？请君听我明日歌。","tags":["劝学","惜时","名篇"]},{"id":"ming_004","title":"桃花庵歌","author":"唐寅","dynasty":"明","dynastyCode":"ming","content":"桃花坞里桃花庵，桃花庵下桃花仙。桃花仙人种桃树，又摘桃花换酒钱。酒醒只在花前坐，酒醉还来花下眠。半醒半醉日复日，花落花开年复年。但愿老死花酒间，不愿鞠躬车马前。别人笑我太疯癫，我笑他人看不穿。不见五陵豪杰墓，无花无酒锄作田。","tags":["桃花","隐逸","名篇","唐伯虎"]},{"id":"ming_005","title":"送东阳马生序","author":"宋濂","dynasty":"明","dynastyCode":"ming","content":"余幼时即嗜学。家贫，无从致书以观，每假借于藏书之家，手自笔录，计日以还。天大寒，砚冰坚，手指不可屈伸，弗之怠。录毕，走送之，不敢稍逾约。以是人多以书假余，余因得遍观群书。既加冠，益慕圣贤之道……其业有不精、德有不成者，非天质之卑，则心不若余之专耳，岂他人之过哉？","tags":["劝学","散文","初中必背"]},{"id":"ming_006","title":"项脊轩志","author":"归有光","dynasty":"明","dynastyCode":"ming","content":"项脊轩，旧南阁子也。室仅方丈，可容一人居。百年老屋，尘泥渗漉，雨泽下注；每移案，顾视无可置者。又北向，不能得日，日过午已昏。余稍为修葺，使不上漏。前辟四窗，垣墙周庭，以当南日，日影反照，室始洞然。又杂植兰桂竹木于庭，旧时栏楯，亦遂增胜。借书满架，偃仰啸歌，冥然兀坐，万籁有声；而庭阶寂寂，小鸟时来啄食，人至不去。三五之夜，明月半墙，桂影斑驳，风移影动，珊珊可爱。庭有枇杷树，吾妻死之年所手植也，今已亭亭如盖矣。","tags":["抒情","散文","高中必背"]},{"id":"ming_007","title":"登金陵雨花台望大江","author":"高启","dynasty":"明","dynastyCode":"ming","content":"大江来从万山中，山势尽与江流东。钟山如龙独西上，欲破巨浪乘长风。江山相雄不相让，形胜争夸天下壮。秦皇空此瘗黄金，佳气葱葱至今王。","tags":["七言古诗","怀古","高启","名篇"]},{"id":"ming_008","title":"牡丹亭·游园惊梦","author":"汤显祖","dynasty":"明","dynastyCode":"ming","content":"原来姹紫嫣红开遍，似这般都付与断井颓垣。良辰美景奈何天，赏心乐事谁家院？朝飞暮卷，云霞翠轩；雨丝风片，烟波画船。锦屏人忒看得这韶光贱！","tags":["昆曲","爱情","名篇","汤显祖"]},{"id":"ming_009","title":"浣溪沙·谁道闲情抛弃久","author":"杨慎","dynasty":"明","dynastyCode":"ming","content":"谁道闲情抛弃久？每到春来，惆怅还依旧。日日花前常病酒，不辞镜里朱颜瘦。河畔青芜堤上柳，为问新愁，何事年年有？独立小桥风满袖，平林新月人归后。","tags":["明词","婉约","名篇"]},{"id":"qing_001","title":"己亥杂诗·其五","author":"龚自珍","dynasty":"清","dynastyCode":"qing","content":"浩荡离愁白日斜，吟鞭东指即天涯。\n落红不是无情物，化作春泥更护花。","tags":["爱国","名篇","初中必背","龚自珍"]},{"id":"qing_002","title":"长相思·山一程","author":"纳兰性德","dynasty":"清","dynastyCode":"qing","content":"山一程，水一程，\n身向榆关那畔行，夜深千帐灯。\n\n风一更，雪一更，\n聒碎乡心梦不成，故园无此声。","tags":["清词","边塞","思乡","小学必背","纳兰性德"]},{"id":"qing_003","title":"论诗五首·其二","author":"赵翼","dynasty":"清","dynastyCode":"qing","content":"李杜诗篇万口传，至今已觉不新鲜。\n江山代有才人出，各领风骚数百年。","tags":["评论","名篇","哲理","初中必背","赵翼"]},{"id":"qing_004","title":"竹石","author":"郑燮","dynasty":"清","dynastyCode":"qing","content":"咬定青山不放松，立根原在破岩中。\n千磨万击还坚劲，任尔东西南北风。","tags":["咏物","题画","名篇","小学必背","郑板桥"]},{"id":"qing_005","title":"村居","author":"高鼎","dynasty":"清","dynastyCode":"qing","content":"草长莺飞二月天，拂堤杨柳醉春烟。\n儿童散学归来早，忙趁东风放纸鸢。","tags":["田园","春天","名篇","小学必背"]},{"id":"qing_006","title":"河中石兽","author":"纪昀","dynasty":"清","dynastyCode":"qing","content":"沧州南一寺临河干，山门圮于河，二石兽并沉焉。阅十余岁，僧募金重修，求二石兽于水中，竟不可得，以为顺流下矣。棹数小舟，曳铁钯，寻十余里无迹。\n一讲学家设帐寺中，闻之笑曰：'尔辈不能究物理。是非木杮，岂能为暴涨携之去？乃石性坚重，沙性松浮，湮于沙上，渐沉渐深耳。沿河求之，不亦颠乎？'众服为确论。\n一老河兵闻之，又笑曰：'凡河中失石，当求之于上流。盖石性坚重，沙性松浮，水不能冲石，其反激之力，必于石下迎水处啮沙为坎穴。渐激渐深，至石之半，石必倒掷坎穴中。如是再啮，石又再转。转转不已，遂反溯流逆上矣。求之下流，固颠；求之地中，不更颠乎？'如其言，果得于数里外。然则天下之事，但知其一，不知其二者多矣，可据理臆断欤？","tags":["散文","寓言","初中必背","纪晓岚"]},{"id":"qing_007","title":"登泰山记","author":"姚鼐","dynasty":"清","dynastyCode":"qing","content":"泰山之阳，汶水西流；其阴，济水东流。阳谷皆入汶，阴谷皆入济。当其南北分者，古长城也。最高日观峰，在长城南十五里。\n余以乾隆三十九年十二月，自京师乘风雪，历齐河、长清，穿泰山西北谷，越长城之限，至于泰安。是月丁未，与知府朱孝纯子颍由南麓登。四十五里，道皆砌石为磴，其级七千有余。泰山正南面有三谷。中谷绕泰安城下，郦道元所谓环水也。余始循以入，道少半，越中岭，复循西谷，遂至其巅。古时登山，循东谷入，道有天门。东谷者，古谓之天门溪水，余所不至也。今所经中岭及山巅崖限当道者，世皆谓之天门云。道中迷雾冰滑，磴几不可登。及既上，苍山负雪，明烛天南。望晚日照城郭，汶水、徂徕如画，而半山居雾若带然。\n戊申晦，五鼓，与子颍坐日观亭，待日出。大风扬积雪击面。亭东自足下皆云漫。稍见云中白若樗蒱数十立者，山也。极天云一线异色，须臾成五采。日上，正赤如丹，下有红光动摇承之，或曰，此东海也。回视日观以西峰，或得日或否，绛皓驳色，而皆若偻。\n亭西有岱祠，又有碧霞元君祠。皇帝行宫在碧霞元君祠东。是日观道中石刻，自唐显庆以来；其远古刻尽漫失。僻不当道者，皆不及往。\n山多石，少土。石苍黑色，多平方，少圜。少杂树，多松，生石罅，皆平顶。冰雪，无瀑水，无鸟兽音迹。至日观数里内无树，而雪与人膝齐。\n桐城姚鼐记。","tags":["散文","游记","高中必背","桐城派","姚鼐"]},{"id":"qing_008","title":"病梅馆记","author":"龚自珍","dynasty":"清","dynastyCode":"qing","content":"江宁之龙蟠，苏州之邓尉，杭州之西溪，皆产梅。或曰：梅以曲为美，直则无姿；以欹为美，正则无景；以疏为美，密则无态。固也。此文人画士心知其意，未可明诏大号以绳天下之梅也；又不可以使天下之民斫直，删密，锄正，以夭梅病梅为业以求钱也。梅之欹之疏之曲，又非蠢蠢求钱之民能以其智力为也。有以文人画士孤癖之隐明告鬻梅者，斫其正，养其旁条，删其密，夭其稚枝，锄其直，遏其生气，以求重价，而江浙之梅皆病。文人画士之祸之烈至此哉！\n予购三百盆，皆病者，无一完者。既泣之三日，乃誓疗之：纵之顺之，毁其盆，悉埋于地，解其棕缚；以五年为期，必复之全之。孤之闲之，以求其复也。呜呼！安得使予多暇日，又多闲田，以广贮江宁、杭州、苏州之病梅，穷予生之光阴以疗梅也哉！","tags":["散文","托物言志","高中必背","龚自珍"]},{"id":"qing_009","title":"满江红·小住京华","author":"秋瑾","dynasty":"清","dynastyCode":"qing","content":"小住京华，早又是，中秋佳节。为篱下，黄花开遍，秋容如拭。四面歌残终破楚，八年风味徒思浙。苦将侬，强派作蛾眉，殊未屑！\n身不得，男儿列。心却比，男儿烈！算平生肝胆，因人常热。俗子胸襟谁识我？英雄末路当磨折。莽红尘，何处觅知音？青衫湿！","tags":["清词","豪放","初中必背","秋瑾"]},{"id":"qing_010","title":"己亥杂诗·其二百二十","author":"龚自珍","dynasty":"清","dynastyCode":"qing","content":"九州生气恃风雷，万马齐喑究可哀。\n我劝天公重抖擞，不拘一格降人才。","tags":["爱国","名篇","初中必背","龚自珍"]},{"id":"qing_011","title":"潼关","author":"谭嗣同","dynasty":"清","dynastyCode":"qing","content":"终古高云簇此城，秋风吹散马蹄声。\n河流大野犹嫌束，山入潼关不解平。","tags":["七言绝句","咏物","初中必背","谭嗣同"]},{"id":"qing_012","title":"狱中题壁","author":"谭嗣同","dynasty":"清","dynastyCode":"qing","content":"望门投止思张俭，忍死须臾待杜根。\n我自横刀向天笑，去留肝胆两昆仑！","tags":["七言绝句","爱国","绝命诗","谭嗣同"]},{"id":"qing_013","title":"所见","author":"袁枚","dynasty":"清","dynastyCode":"qing","content":"牧童骑黄牛，歌声振林樾。\n意欲捕鸣蝉，忽然闭口立。","tags":["五言绝句","童趣","小学必背","袁枚"]},{"id":"qing_014","title":"苔","author":"袁枚","dynasty":"清","dynastyCode":"qing","content":"白日不到处，青春恰自来。\n苔花如米小，也学牡丹开。","tags":["五言绝句","咏物","励志","袁枚"]},{"id":"qing_015","title":"浣溪沙·谁念西风独自凉","author":"纳兰性德","dynasty":"清","dynastyCode":"qing","content":"谁念西风独自凉，萧萧黄叶闭疏窗，沉思往事立残阳。\n被酒莫惊春睡重，赌书消得泼茶香，当时只道是寻常。","tags":["清词","悼亡","名篇","纳兰性德"]},{"id":"qing_016","title":"木兰花令·拟古决绝词","author":"纳兰性德","dynasty":"清","dynastyCode":"qing","content":"人生若只如初见，何事秋风悲画扇。\n等闲变却故人心，却道故人心易变。\n\n骊山语罢清宵半，泪雨霖铃终不怨。\n何如薄幸锦衣郎，比翼连枝当日愿。","tags":["清词","爱情","名句","名篇"]},{"id":"qing_017","title":"蝶恋花","author":"纳兰性德","dynasty":"清","dynastyCode":"qing","content":"辛苦最怜天上月，一昔如环，昔昔都成玦。若似月轮终皎洁，不辞冰雪为卿热。\n\n无那尘缘容易绝，燕子依然，软踏帘钩说。唱罢秋坟愁未歇，春丛认取双栖蝶。","tags":["清词","悼亡","爱情","名篇"]},{"id":"qing_018","title":"潍县署中画竹呈年伯包大中丞括","author":"郑燮","dynasty":"清","dynastyCode":"qing","content":"衙斋卧听萧萧竹，疑是民间疾苦声。\n些小吾曹州县吏，一枝一叶总关情。","tags":["七言绝句","咏物","民生","初中必背"]},{"id":"qing_019","title":"赴戍登程口占示家人","author":"林则徐","dynasty":"清","dynastyCode":"qing","content":"力微任重久神疲，再竭衰庸定不支。\n苟利国家生死以，岂因祸福避趋之。\n谪居正是君恩厚，养拙刚于戍卒宜。\n戏与山妻谈故事，试吟断送老头皮。","tags":["七言律诗","爱国","名句","高中必背"]},{"id":"qing_020","title":"杂感","author":"黄景仁","dynasty":"清","dynastyCode":"qing","content":"仙佛茫茫两未成，只知独夜不平鸣。\n风尘荏苒音书绝，关塞萧条行路难。\n已忍伶俜十年事，心持半偈万缘空。\n十有九人堪白眼，百无一用是书生。","tags":["七言律诗","感怀","名句","名篇"]},{"id":"qing_021","title":"野步","author":"赵翼","dynasty":"清","dynastyCode":"qing","content":"峭寒催换木棉裘，倚杖郊原作近游。\n最是秋风管闲事，红他枫叶白人头。","tags":["七言绝句","写景","哲理","名篇"]},{"id":"qing_022","title":"江上","author":"王士禛","dynasty":"清","dynastyCode":"qing","content":"吴头楚尾路如何？烟雨秋深暗白波。\n晚趁寒潮渡江去，满林黄叶雁声多。","tags":["七言绝句","山水","写景","名篇"]},{"id":"qing_023","title":"蝶恋花·阅尽天涯离别苦","author":"王国维","dynasty":"清","dynastyCode":"qing","content":"阅尽天涯离别苦，不道归来，零落花如许。花底相看无一语，绿窗春与天俱莫。\n\n待把相思灯下诉，一缕新欢，旧恨千千缕。最是人间留不住，朱颜辞镜花辞树。","tags":["清词","感怀","名句","名篇"]},{"id":"qing_024","title":"湖上杂诗","author":"袁枚","dynasty":"清","dynastyCode":"qing","content":"葛岭花开二月天，游人来往说神仙。\n老夫心与游人异，不羡神仙羡少年。","tags":["七言绝句","写景","感怀","名篇"]},{"id":"qing_025","title":"对酒","author":"秋瑾","dynasty":"清","dynastyCode":"qing","content":"不惜千金买宝刀，貂裘换酒也堪豪。\n一腔热血勤珍重，洒去犹能化碧涛。","tags":["七言绝句","爱国","豪放","初中必背"]},{"id":"qing_026","title":"木兰花慢·拟古决绝词","author":"纳兰性德","dynasty":"清","dynastyCode":"qing","content":"人生若只如初见，何事秋风悲画扇。等闲变却故人心，却道故人心易变。骊山语罢清宵半，泪雨霖铃终不怨。何如薄幸锦衣郎，比翼连枝当日愿。","tags":["清词","爱情","名篇","纳兰性德"]},{"id":"qing_027","title":"己亥杂诗·其一百二十五","author":"龚自珍","dynasty":"清","dynastyCode":"qing","content":"九州生气恃风雷，万马齐喑究可哀。我劝天公重抖擞，不拘一格降人才。","tags":["爱国","改革","初中必背","龚自珍"]},{"id":"song_001","title":"水调歌头·明月几时有","author":"苏轼","dynasty":"宋","dynastyCode":"song","content":"明月几时有？把酒问青天。\n不知天上宫阙，今夕是何年。\n我欲乘风归去，又恐琼楼玉宇，高处不胜寒。\n起舞弄清影，何似在人间。\n\n转朱阁，低绮户，照无眠。\n不应有恨，何事长向别时圆？\n人有悲欢离合，月有阴晴圆缺，此事古难全。\n但愿人长久，千里共婵娟。","tags":["宋词","中秋","豪放派","高中必背","苏轼"]},{"id":"song_002","title":"念奴娇·赤壁怀古","author":"苏轼","dynasty":"宋","dynastyCode":"song","content":"大江东去，浪淘尽，千古风流人物。\n故垒西边，人道是，三国周郎赤壁。\n乱石穿空，惊涛拍岸，卷起千堆雪。\n江山如画，一时多少豪杰。\n\n遥想公瑾当年，小乔初嫁了，雄姿英发。\n羽扇纶巾，谈笑间，樯橹灰飞烟灭。\n故国神游，多情应笑我，早生华发。\n人生如梦，一尊还酹江月。","tags":["宋词","怀古","豪放派","高中必背","苏轼"]},{"id":"song_003","title":"声声慢·寻寻觅觅","author":"李清照","dynasty":"宋","dynastyCode":"song","content":"寻寻觅觅，冷冷清清，凄凄惨惨戚戚。\n乍暖还寒时候，最难将息。\n三杯两盏淡酒，怎敌他、晚来风急？\n雁过也，正伤心，却是旧时相识。\n\n满地黄花堆积。憔悴损，如今有谁堪摘？\n守着窗儿，独自怎生得黑？\n梧桐更兼细雨，到黄昏、点点滴滴。\n这次第，怎一个愁字了得！","tags":["宋词","婉约派","愁绪","高中必背","李清照"]},{"id":"song_004","title":"如梦令·昨夜雨疏风骤","author":"李清照","dynasty":"宋","dynastyCode":"song","content":"昨夜雨疏风骤，浓睡不消残酒。\n试问卷帘人，却道海棠依旧。\n知否，知否？应是绿肥红瘦。","tags":["宋词","婉约派","惜春","初中必背","李清照"]},{"id":"song_005","title":"满江红·写怀","author":"岳飞","dynasty":"宋","dynastyCode":"song","content":"怒发冲冠，凭栏处、潇潇雨歇。\n抬望眼，仰天长啸，壮怀激烈。\n三十功名尘与土，八千里路云和月。\n莫等闲，白了少年头，空悲切！\n\n靖康耻，犹未雪。臣子恨，何时灭！\n驾长车，踏破贺兰山缺。\n壮志饥餐胡虏肉，笑谈渴饮匈奴血。\n待从头、收拾旧山河，朝天阙。","tags":["宋词","爱国","豪放","初中必背","岳飞"]},{"id":"song_006","title":"雨霖铃·寒蝉凄切","author":"柳永","dynasty":"宋","dynastyCode":"song","content":"寒蝉凄切，对长亭晚，骤雨初歇。\n都门帐饮无绪，留恋处，兰舟催发。\n执手相看泪眼，竟无语凝噎。\n念去去，千里烟波，暮霭沉沉楚天阔。\n\n多情自古伤离别，更那堪，冷落清秋节！\n今宵酒醒何处？杨柳岸，晓风残月。\n此去经年，应是良辰好景虚设。\n便纵有千种风情，更与何人说？","tags":["宋词","婉约派","离别","高中必背","柳永"]},{"id":"song_007","title":"岳阳楼记","author":"范仲淹","dynasty":"宋","dynastyCode":"song","content":"庆历四年春，滕子京谪守巴陵郡。越明年，政通人和，百废具兴，乃重修岳阳楼，增其旧制，刻唐贤今人诗赋于其上，属予作文以记之。\n\n予观夫巴陵胜状，在洞庭一湖。衔远山，吞长江，浩浩汤汤，横无际涯，朝晖夕阴，气象万千，此则岳阳楼之大观也，前人之述备矣。然则北通巫峡，南极潇湘，迁客骚人，多会于此，览物之情，得无异乎？\n\n若夫淫雨霏霏，连月不开，阴风怒号，浊浪排空，日星隐曜，山岳潜形，商旅不行，樯倾楫摧，薄暮冥冥，虎啸猿啼。登斯楼也，则有去国怀乡，忧谗畏讥，满目萧然，感极而悲者矣。\n\n至若春和景明，波澜不惊，上下天光，一碧万顷，沙鸥翔集，锦鳞游泳，岸芷汀兰，郁郁青青。而或长烟一空，皓月千里，浮光跃金，静影沉璧，渔歌互答，此乐何极！登斯楼也，则有心旷神怡，宠辱偕忘，把酒临风，其喜洋洋者矣。\n\n嗟夫！予尝求古仁人之心，或异二者之为，何哉？不以物喜，不以己悲，居庙堂之高则忧其民，处江湖之远则忧其君。是进亦忧，退亦忧。然则何时而乐耶？其必曰先天下之忧而忧，后天下之乐而乐乎！噫！微斯人，吾谁与归？时六年九月十五日。","tags":["古文","哲理","名篇","高中必背","岳阳楼"]},{"id":"song_008","title":"赤壁赋","author":"苏轼","dynasty":"宋","dynastyCode":"song","content":"壬戌之秋，七月既望，苏子与客泛舟游于赤壁之下。清风徐来，水波不兴。举酒属客，诵明月之诗，歌窈窕之章。少焉，月出于东山之上，徘徊于斗牛之间。白露横江，水光接天。纵一苇之所如，凌万顷之茫然。浩浩乎如冯虚御风，而不知其所止；飘飘乎如遗世独立，羽化而登仙。\n\n于是饮酒乐甚，扣舷而歌之。歌曰：桂棹兮兰桨，击空明兮溯流光。渺渺兮予怀，望美人兮天一方。客有吹洞箫者，倚歌而和之。其声呜呜然，如怨如慕，如泣如诉，余音袅袅，不绝如缕。舞幽壑之潜蛟，泣孤舟之嫠妇。\n\n苏子愀然，正襟危坐而问客曰：何为其然也？客曰：月明星稀，乌鹊南飞，此非曹孟德之诗乎？西望夏口，东望武昌，山川相缪，郁乎苍苍，此非孟德之困于周郎者乎？方其破荆州，下江陵，顺流而东也，舳舻千里，旌旗蔽空，酾酒临江，横槊赋诗，固一世之雄也，而今安在哉？况吾与子渔樵于江渚之上，侣鱼虾而友麋鹿，驾一叶之扁舟，举匏樽以相属。寄蜉蝣于天地，渺沧海之一粟。哀吾生之须臾，羡长江之无穷。挟飞仙以遨游，抱明月而长终。知不可乎骤得，托遗响于悲风。\n\n苏子曰：客亦知夫水与月乎？逝者如斯，而未尝往也；盈虚者如彼，而卒莫消长也。盖将自其变者而观之，则天地曾不能以一瞬；自其不变者而观之，则物与我皆无尽也，而又何羡乎！且夫天地之间，物各有主，苟非吾之所有，虽一毫而莫取。惟江上之清风，与山间之明月，耳得之而为声，目遇之而成色，取之无禁，用之不竭，是造物者之无尽藏也，而吾与子之所共适。\n\n客喜而笑，洗盏更酌。肴核既尽，杯盘狼籍。相与枕藉乎舟中，不知东方之既白。","tags":["赋","哲理","名篇","高中必背","赤壁"]},{"id":"song_009","title":"游山西村","author":"陆游","dynasty":"宋","dynastyCode":"song","content":"莫笑农家腊酒浑，丰年留客足鸡豚。\n山重水复疑无路，柳暗花明又一村。\n箫鼓追随春社近，衣冠简朴古风存。\n从今若许闲乘月，拄杖无时夜叩门。","tags":["宋诗","山水","哲理","初中必背","陆游"]},{"id":"song_010","title":"南乡子·登京口北固亭有怀","author":"辛弃疾","dynasty":"宋","dynastyCode":"song","content":"何处望神州？满眼风光北固楼。\n千古兴亡多少事？悠悠。\n不尽长江滚滚流。\n\n年少万兜鍪，坐断东南战未休。\n天下英雄谁敌手？曹刘。\n生子当如孙仲谋。","tags":["宋词","怀古","豪放派","初中必背","辛弃疾"]},{"id":"song_011","title":"破阵子·为陈同甫赋壮词以寄之","author":"辛弃疾","dynasty":"宋","dynastyCode":"song","content":"醉里挑灯看剑，梦回吹角连营。\n八百里分麾下炙，五十弦翻塞外声，沙场秋点兵。\n\n马作的卢飞快，弓如霹雳弦惊。\n了却君王天下事，赢得生前身后名。可怜白发生！","tags":["宋词","豪放派","壮志","初中必背","辛弃疾"]},{"id":"song_012","title":"过零丁洋","author":"文天祥","dynasty":"宋","dynastyCode":"song","content":"辛苦遭逢起一经，干戈寥落四周星。\n山河破碎风飘絮，身世浮沉雨打萍。\n惶恐滩头说惶恐，零丁洋里叹零丁。\n人生自古谁无死？留取丹心照汗青。","tags":["宋诗","爱国","忠贞","初中必背","文天祥"]},{"id":"song_013","title":"醉翁亭记","author":"欧阳修","dynasty":"宋","dynastyCode":"song","content":"环滁皆山也。其西南诸峰，林壑尤美，望之蔚然而深秀者，琅琊也。山行六七里，渐闻水声潺潺，而泻出于两峰之间者，酿泉也。峰回路转，有亭翼然临于泉上者，醉翁亭也。作亭者谁？山之僧智仙也。名之者谁？太守自谓也。太守与客来饮于此，饮少辄醉，而年又最高，故自号曰醉翁也。醉翁之意不在酒，在乎山水之间也。山水之乐，得之心而寓之酒也。\n\n若夫日出而林霏开，云归而岩穴暝，晦明变化者，山间之朝暮也。野芳发而幽香，佳木秀而繁阴，风霜高洁，水落而石出者，山间之四时也。朝而往，暮而归，四时之景不同，而乐亦无穷也。\n\n至于负者歌于途，行者休于树，前者呼，后者应，伛偻提携，往来而不绝者，滁人游也。临溪而渔，溪深而鱼肥，酿泉为酒，泉香而酒洌，山肴野蔌，杂然而前陈者，太守宴也。宴酣之乐，非丝非竹，射者中，弈者胜，觥筹交错，起坐而喧哗者，众宾欢也。苍颜白发，颓然乎其间者，太守醉也。\n\n已而夕阳在山，人影散乱，太守归而宾客从也。树林阴翳，鸣声上下，游人去而禽鸟乐也。然而禽鸟知山林之乐，而不知人之乐；人知从太守游而乐，而不知太守之乐其乐也。醉能同其乐，醒能述以文者，太守也。太守谓谁？庐陵欧阳修也。","tags":["古文","山水","哲理","初中必背","欧阳修"]},{"id":"song_014","title":"江城子·密州出猎","author":"苏轼","dynasty":"宋","dynastyCode":"song","content":"老夫聊发少年狂，左牵黄，右擎苍，锦帽貂裘，千骑卷平冈。\n为报倾城随太守，亲射虎，看孙郎。\n\n酒酣胸胆尚开张。鬓微霜，又何妨！持节云中，何日遣冯唐？\n会挽雕弓如满月，西北望，射天狼。","tags":["宋词","豪放派","壮志","初中必背","苏轼"]},{"id":"song_015","title":"定风波","author":"苏轼","dynasty":"宋","dynastyCode":"song","content":"莫听穿林打叶声，何妨吟啸且徐行。竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。\n\n料峭春风吹酒醒，微冷，山头斜照却相迎。回首向来萧瑟处，归去，也无风雨也无晴。","tags":["宋词","豪放派","哲理","高中必背","苏轼"]},{"id":"song_016","title":"鹊桥仙·纤云弄巧","author":"秦观","dynasty":"宋","dynastyCode":"song","content":"纤云弄巧，飞星传恨，银汉迢迢暗度。\n金风玉露一相逢，便胜却人间无数。\n\n柔情似水，佳期如梦，忍顾鹊桥归路。\n两情若是久长时，又岂在朝朝暮暮。","tags":["宋词","婉约派","爱情","高中必背","秦观"]},{"id":"song_017","title":"苏幕遮·燎沉香","author":"周邦彦","dynasty":"宋","dynastyCode":"song","content":"燎沉香，消溽暑。鸟雀呼晴，侵晓窥檐语。\n叶上初阳干宿雨，水面清圆，一一风荷举。\n\n故乡遥，何日去？家住吴门，久作长安旅。\n五月渔郎相忆否？小楫轻舟，梦入芙蓉浦。","tags":["宋词","婉约派","思乡","高中必背","周邦彦"]},{"id":"song_018","title":"桂枝香·金陵怀古","author":"王安石","dynasty":"宋","dynastyCode":"song","content":"登临送目，正故国晚秋，天气初肃。\n千里澄江似练，翠峰如簇。\n归帆去棹残阳里，背西风，酒旗斜矗。\n彩舟云淡，星河鹭起，画图难足。\n\n念往昔，繁华竞逐，叹门外楼头，悲恨相续。\n千古凭高对此，谩嗟荣辱。\n六朝旧事随流水，但寒烟衰草凝绿。\n至今商女，时时犹唱，后庭遗曲。","tags":["宋词","怀古","豪放","高中必背","王安石"]},{"id":"song_019","title":"江城子·乙卯正月二十日夜记梦","author":"苏轼","dynasty":"宋","dynastyCode":"song","content":"十年生死两茫茫，不思量，自难忘。\n千里孤坟，无处话凄凉。\n纵使相逢应不识，尘满面，鬓如霜。\n\n夜来幽梦忽还乡，小轩窗，正梳妆。\n相顾无言，惟有泪千行。\n料得年年肠断处，明月夜，短松冈。","tags":["宋词","婉约派","悼亡","高中必背","苏轼"]},{"id":"song_020","title":"登快阁","author":"黄庭坚","dynasty":"宋","dynastyCode":"song","content":"痴儿了却公家事，快阁东西倚晚晴。\n落木千山天远大，澄江一道月分明。\n朱弦已为佳人绝，青眼聊因美酒横。\n万里归船弄长笛，此心吾与白鸥盟。","tags":["宋诗","山水","闲适","高中必背","黄庭坚"]},{"id":"song_021","title":"书愤","author":"陆游","dynasty":"宋","dynastyCode":"song","content":"早岁那知世事艰，中原北望气如山。\n楼船夜雪瓜洲渡，铁马秋风大散关。\n塞上长城空自许，镜中衰鬓已先斑。\n出师一表真名世，千载谁堪伯仲间！","tags":["宋诗","爱国","壮志","高中必背","陆游"]},{"id":"song_022","title":"临安春雨初霁","author":"陆游","dynasty":"宋","dynastyCode":"song","content":"世味年来薄似纱，谁令骑马客京华？\n小楼一夜听春雨，深巷明朝卖杏花。\n矮纸斜行闲作草，晴窗细乳戏分茶。\n素衣莫起风尘叹，犹及清明可到家。","tags":["宋诗","闲适","讽刺","高中必背","陆游"]},{"id":"song_023","title":"永遇乐·京口北固亭怀古","author":"辛弃疾","dynasty":"宋","dynastyCode":"song","content":"千古江山，英雄无觅孙仲谋处。\n舞榭歌台，风流总被雨打风吹去。\n斜阳草树，寻常巷陌，人道寄奴曾住。\n想当年，金戈铁马，气吞万里如虎。\n\n元嘉草草，封狼居胥，赢得仓皇北顾。\n四十三年，望中犹记，烽火扬州路。\n可堪回首，佛狸祠下，一片神鸦社鼓。\n凭谁问：廉颇老矣，尚能饭否？","tags":["宋词","豪放派","怀古","高中必背","辛弃疾"]},{"id":"song_024","title":"菩萨蛮·书江西造口壁","author":"辛弃疾","dynasty":"宋","dynastyCode":"song","content":"郁孤台下清江水，中间多少行人泪。\n西北望长安，可怜无数山。\n\n青山遮不住，毕竟东流去。\n江晚正愁余，山深闻鹧鸪。","tags":["宋词","豪放派","爱国","高中必背","辛弃疾"]},{"id":"song_025","title":"青玉案·元夕","author":"辛弃疾","dynasty":"宋","dynastyCode":"song","content":"东风夜放花千树，更吹落、星如雨。\n宝马雕车香满路。\n凤箫声动，玉壶光转，一夜鱼龙舞。\n\n蛾儿雪柳黄金缕，笑语盈盈暗香去。\n众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。","tags":["宋词","豪放派","元宵","高中必背","辛弃疾"]},{"id":"song_026","title":"扬州慢","author":"姜夔","dynasty":"宋","dynastyCode":"song","content":"淮左名都，竹西佳处，解鞍少驻初程。\n过春风十里，尽荠麦青青。\n自胡马窥江去后，废池乔木，犹厌言兵。\n渐黄昏，清角吹寒，都在空城。\n\n杜郎俊赏，算而今、重到须惊。\n纵豆蔻词工，青楼梦好，难赋深情。\n二十四桥仍在，波心荡、冷月无声。\n念桥边红药，年年知为谁生？","tags":["宋词","婉约派","黍离之悲","高中必背","姜夔"]},{"id":"song_027","title":"念奴娇·过洞庭","author":"张孝祥","dynasty":"宋","dynastyCode":"song","content":"洞庭青草，近中秋，更无一点风色。\n玉鉴琼田三万顷，着我扁舟一叶。\n素月分辉，明河共影，表里俱澄澈。\n悠然心会，妙处难与君说。\n\n应念岭表经年，孤光自照，肝胆皆冰雪。\n短发萧骚襟袖冷，稳泛沧浪空阔。\n尽挹西江，细斟北斗，万象为宾客。\n扣舷独啸，不知今夕何夕。","tags":["宋词","豪放派","山水","高中必背","张孝祥"]},{"id":"song_028","title":"贺新郎·国脉微如缕","author":"刘克庄","dynasty":"宋","dynastyCode":"song","content":"国脉微如缕。问长缨何时入手，缚将戎主？\n未必人间无好汉，谁与宽些尺度？\n试看取当年韩五。岂有谷城公付授，也不干曾遇骊山母。\n谈笑起，两河路。\n\n少时棋柝曾联句。叹而今登楼揽镜，事机频误。\n闻说北风吹面急，边上冲梯屡舞。\n君莫道投鞭虚语。自古一贤能制难，有金汤便可无张许？\n快投笔，莫题柱。","tags":["宋词","豪放派","爱国","高中必背","刘克庄"]},{"id":"song_029","title":"答司马谏议书","author":"王安石","dynasty":"宋","dynastyCode":"song","content":"某启：昨日蒙教，窃以为与君实游处相好之日久，而议事每不合，所操之术多异故也。虽欲强聒，终必不蒙见察，故略上报，不复一一自辨。重念蒙君实视遇厚，于反复不宜卤莽，故今具道所以，冀君实或见恕也。\n\n盖儒者所争，尤在于名实，名实已明，而天下之理得矣。今君实所以见教者，以为侵官、生事、征利、拒谏，以致天下怨谤也。某则以谓受命于人主，议法度而修之于朝廷，以授之于有司，不为侵官；举先王之政，以兴利除弊，不为生事；为天下理财，不为征利；辟邪说，难壬人，不为拒谏。至于怨诽之多，则固前知其如此也。\n\n人习于苟且非一日，士大夫多以不恤国事、同俗自媚于众为善，上乃欲变此，而某不量敌之众寡，欲出力助上以抗之，则众何为而不汹汹然？盘庚之迁，胥怨者民也，非特朝廷士大夫而已；盘庚不为怨者故改其度，度义而后动，是而不见可悔故也。如君实责我以在位久，未能助上大有为，以膏泽斯民，则某知罪矣；如曰今日当一切不事事，守前所为而已，则非某之所敢知。\n\n无由会晤，不任区区向往之至！","tags":["古文","政论","名篇","高中必背","王安石"]},{"id":"song_030","title":"记承天寺夜游","author":"苏轼","dynasty":"宋","dynastyCode":"song","content":"元丰六年十月十二日夜，解衣欲睡，月色入户，欣然起行。念无与为乐者，遂至承天寺寻张怀民。怀民亦未寝，相与步于中庭。庭下如积水空明，水中藻、荇交横，盖竹柏影也。何夜无月？何处无竹柏？但少闲人如吾两人者耳。","tags":["古文","小品","名篇","初中必背","苏轼"]},{"id":"song_031","title":"爱莲说","author":"周敦颐","dynasty":"宋","dynastyCode":"song","content":"水陆草木之花，可爱者甚蕃。晋陶渊明独爱菊。自李唐来，世人甚爱牡丹。予独爱莲之出淤泥而不染，濯清涟而不妖，中通外直，不蔓不枝，香远益清，亭亭净植，可远观而不可亵玩焉。\n\n予谓菊，花之隐逸者也；牡丹，花之富贵者也；莲，花之君子者也。噫！菊之爱，陶后鲜有闻。莲之爱，同予者何人？牡丹之爱，宜乎众矣！","tags":["古文","哲理","名篇","初中必背","周敦颐"]},{"id":"song_032","title":"观书有感·其一","author":"朱熹","dynasty":"宋","dynastyCode":"song","content":"半亩方塘一鉴开，天光云影共徘徊。\n问渠那得清如许？为有源头活水来。","tags":["宋诗","哲理","劝学","小学必背","朱熹"]},{"id":"song_033","title":"题临安邸","author":"林升","dynasty":"宋","dynastyCode":"song","content":"山外青山楼外楼，西湖歌舞几时休？\n暖风熏得游人醉，直把杭州作汴州。","tags":["宋诗","讽刺","爱国","小学必背","林升"]},{"id":"song_034","title":"游园不值","author":"叶绍翁","dynasty":"宋","dynastyCode":"song","content":"应怜屐齿印苍苔，小扣柴扉久不开。\n春色满园关不住，一枝红杏出墙来。","tags":["宋诗","写景","哲理","小学必背","叶绍翁"]},{"id":"song_035","title":"乡村四月","author":"翁卷","dynasty":"宋","dynastyCode":"song","content":"绿遍山原白满川，子规声里雨如烟。\n乡村四月闲人少，才了蚕桑又插田。","tags":["宋诗","田园","农事","小学必背","翁卷"]},{"id":"song_036","title":"渔家傲·秋思","author":"范仲淹","dynasty":"宋","dynastyCode":"song","content":"塞下秋来风景异，衡阳雁去无留意。\n四面边声连角起，千嶂里，长烟落日孤城闭。\n\n浊酒一杯家万里，燕然未勒归无计。\n羌管悠悠霜满地，人不寐，将军白发征夫泪。","tags":["宋词","边塞","豪放","初中必背","范仲淹"]},{"id":"song_037","title":"泊船瓜洲","author":"王安石","dynasty":"宋","dynastyCode":"song","content":"京口瓜洲一水间，钟山只隔数重山。\n春风又绿江南岸，明月何时照我还？","tags":["宋诗","思乡","名篇","小学必背","王安石"]},{"id":"song_038","title":"题西林壁","author":"苏轼","dynasty":"宋","dynastyCode":"song","content":"横看成岭侧成峰，远近高低各不同。\n不识庐山真面目，只缘身在此山中。","tags":["宋诗","哲理","山水","小学必背","苏轼"]},{"id":"song_039","title":"惠崇春江晚景","author":"苏轼","dynasty":"宋","dynastyCode":"song","content":"竹外桃花三两枝，春江水暖鸭先知。\n蒌蒿满地芦芽短，正是河豚欲上时。","tags":["宋诗","题画","春天","小学必背","苏轼"]},{"id":"song_040","title":"饮湖上初晴后雨","author":"苏轼","dynasty":"宋","dynastyCode":"song","content":"水光潋滟晴方好，山色空蒙雨亦奇。\n欲把西湖比西子，淡妆浓抹总相宜。","tags":["宋诗","写景","西湖","小学必背","苏轼"]},{"id":"song_041","title":"示儿","author":"陆游","dynasty":"宋","dynastyCode":"song","content":"死去元知万事空，但悲不见九州同。\n王师北定中原日，家祭无忘告乃翁。","tags":["宋诗","爱国","绝笔","小学必背","陆游"]},{"id":"song_042","title":"十一月四日风雨大作","author":"陆游","dynasty":"宋","dynastyCode":"song","content":"僵卧孤村不自哀，尚思为国戍轮台。\n夜阑卧听风吹雨，铁马冰河入梦来。","tags":["宋诗","爱国","壮志","初中必背","陆游"]},{"id":"song_043","title":"小池","author":"杨万里","dynasty":"宋","dynastyCode":"song","content":"泉眼无声惜细流，树阴照水爱晴柔。\n小荷才露尖尖角，早有蜻蜓立上头。","tags":["宋诗","写景","夏天","小学必背","杨万里"]},{"id":"song_044","title":"晓出净慈寺送林子方","author":"杨万里","dynasty":"宋","dynastyCode":"song","content":"毕竟西湖六月中，风光不与四时同。\n接天莲叶无穷碧，映日荷花别样红。","tags":["宋诗","写景","送别","小学必背","杨万里"]},{"id":"song_045","title":"浣溪沙·一曲新词酒一杯","author":"晏殊","dynasty":"宋","dynastyCode":"song","content":"一曲新词酒一杯，去年天气旧亭台。\n夕阳西下几时回？\n\n无可奈何花落去，似曾相识燕归来。\n小园香径独徘徊。","tags":["宋词","婉约派","惜时","初中必背","晏殊"]},{"id":"song_046","title":"一剪梅·红藕香残玉簟秋","author":"李清照","dynasty":"宋","dynastyCode":"song","content":"红藕香残玉簟秋。轻解罗裳，独上兰舟。\n云中谁寄锦书来，雁字回时，月满西楼。\n\n花自飘零水自流。一种相思，两处闲愁。\n此情无计可消除，才下眉头，却上心头。","tags":["宋词","婉约派","相思","高中必背","李清照"]},{"id":"song_047","title":"武陵春·风住尘香花已尽","author":"李清照","dynasty":"宋","dynastyCode":"song","content":"风住尘香花已尽，日晚倦梳头。\n物是人非事事休，欲语泪先流。\n\n闻说双溪春尚好，也拟泛轻舟。\n只恐双溪舴艋舟，载不动许多愁。","tags":["宋词","婉约派","愁绪","高中必背","李清照"]},{"id":"song_048","title":"渔家傲·天接云涛连晓雾","author":"李清照","dynasty":"宋","dynastyCode":"song","content":"天接云涛连晓雾，星河欲转千帆舞。\n仿佛梦魂归帝所。闻天语，殷勤问我归何处。\n\n我报路长嗟日暮，学诗谩有惊人句。\n九万里风鹏正举。风休住，蓬舟吹取三山去！","tags":["宋词","豪放派","名篇","初中必背","李清照"]},{"id":"song_049","title":"诉衷情·当年万里觅封侯","author":"陆游","dynasty":"宋","dynastyCode":"song","content":"当年万里觅封侯，匹马戍梁州。\n关河梦断何处？尘暗旧貂裘。\n\n胡未灭，鬓先秋，泪空流。\n此生谁料，心在天山，身老沧洲。","tags":["宋词","爱国","悲愤","名篇","陆游"]},{"id":"song_050","title":"山园小梅·其一","author":"林逋","dynasty":"宋","dynastyCode":"song","content":"众芳摇落独暄妍，占尽风情向小园。\n疏影横斜水清浅，暗香浮动月黄昏。\n霜禽欲下先偷眼，粉蝶如知合断魂。\n幸有微吟可相狎，不须檀板共金樽。","tags":["宋诗","咏物","梅花","名篇","林逋"]},{"id":"song_051","title":"伤仲永","author":"王安石","dynasty":"宋","dynastyCode":"song","content":"金溪民方仲永，世隶耕。仲永生五年，未尝识书具，忽啼求之。父异焉，借旁近与之，即书诗四句，并自为其名。其诗以养父母、收族为意，传一乡秀才观之。自是指物作诗立就，其文理皆有可观者。邑人奇之，稍稍宾客其父，或以钱币乞之。父利其然也，日扳仲永环谒于邑人，不使学。\n余闻之也久。明道中，从先人还家，于舅家见之，十二三矣。令作诗，不能称前时之闻。又七年，还自扬州，复到舅家问焉。曰：'泯然众人矣。'\n王子曰：仲永之通悟，受之天也。其受之天也，贤于材人远矣。卒之为众人，则其受于人者不至也。彼其受之天也，如此其贤也，不受之人，且为众人；今夫不受之天，固众人，又不受之人，得为众人而已耶？","tags":["古文","议论","教育","初中必背","王安石"]},{"id":"song_052","title":"孙权劝学","author":"司马光","dynasty":"宋","dynastyCode":"song","content":"初，权谓吕蒙曰：''蒙辞以军中多务。权曰：'孤岂欲卿治经为博士邪！但当涉猎，见往事耳。卿言多务，孰若孤？孤常读书，自以为大有所益。'蒙乃始就学。及鲁肃过寻阳，与蒙论议，大惊曰：'卿今者才略，非复吴下阿蒙！'蒙曰：'士别三日，即更刮目相待，大兄何见事之晚乎！'肃遂拜蒙母，结友而别。","tags":["古文","叙事","劝学","初中必背","司马光"]},{"id":"song_053","title":"五代史伶官传序","author":"欧阳修","dynasty":"宋","dynastyCode":"song","content":"呜呼！盛衰之理，虽曰天命，岂非人事哉！原庄宗之所以得天下，与其所以失之者，可以知之矣。\n世言晋王之将终也，以三矢赐庄宗而告之曰：'梁，吾仇也；燕王，吾所立；契丹与吾约为兄弟；而皆背晋以归梁。此三者，吾遗恨也。与尔三矢，尔其无忘乃父之志！'庄宗受而藏之于庙。其后用兵，则遣从事以一少牢告庙，请其矢，盛以锦囊，负而前驱，及凯旋而纳之。\n方其系燕父子以组，函梁君臣之首，入于太庙，还矢先王，而告以成功，其意气之盛，可谓壮哉！及仇雠已灭，天下已定，一夫夜呼，乱者四应，仓皇东出，未及见贼而士卒离散，君臣相顾，不知所归，至于誓天断发，泣下沾襟，何其衰也！岂得之难而失之易欤？本其成败之迹，而皆自于人欤？《书》曰：'满招损，谦受益。'忧劳可以兴国，逸豫可以亡身，自然之理也。\n故方其盛也，举天下之豪杰，莫能与之争；及其衰也，数十伶人困之，而身死国灭，为天下笑。夫祸患常积于忽微，而智勇多困于所溺，岂独伶人也哉？","tags":["古文","史论","名篇","高中必背","欧阳修"]},{"id":"song_054","title":"浣溪沙·游蕲水清泉寺","author":"苏轼","dynasty":"宋","dynastyCode":"song","content":"山下兰芽短浸溪，松间沙路净无泥，萧萧暮雨子规啼。\n谁道人生无再少？门前流水尚能西！休将白发唱黄鸡。","tags":["宋词","豪放派","哲理","苏轼"]},{"id":"song_055","title":"望江南·超然台作","author":"苏轼","dynasty":"宋","dynastyCode":"song","content":"春未老，风细柳斜斜。\n试上超然台上看，半壕春水一城花。烟雨暗千家。\n\n寒食后，酒醒却咨嗟。\n休对故人思故国，且将新火试新茶。诗酒趁年华。","tags":["宋词","豪放派","思乡","苏轼"]},{"id":"song_056","title":"丑奴儿·书博山道中壁","author":"辛弃疾","dynasty":"宋","dynastyCode":"song","content":"少年不识愁滋味，爱上层楼。爱上层楼，为赋新词强说愁。\n\n而今识尽愁滋味，欲说还休。欲说还休，却道天凉好个秋。","tags":["宋词","豪放派","愁绪","初中必背","辛弃疾"]},{"id":"song_057","title":"清平乐·村居","author":"辛弃疾","dynasty":"宋","dynastyCode":"song","content":"茅檐低小，溪上青青草。\n醉里吴音相媚好，白发谁家翁媪？\n\n大儿锄豆溪东，中儿正织鸡笼。\n最喜小儿亡赖，溪头卧剥莲蓬。","tags":["宋词","田园","闲适","初中必背","辛弃疾"]},{"id":"song_058","title":"西江月·夜行黄沙道中","author":"辛弃疾","dynasty":"宋","dynastyCode":"song","content":"明月别枝惊鹊，清风半夜鸣蝉。\n稻花香里说丰年，听取蛙声一片。\n\n七八个星天外，两三点雨山前。\n旧时茅店社林边，路转溪桥忽见。","tags":["宋词","田园","写景","初中必背","辛弃疾"]},{"id":"song_059","title":"夏日绝句","author":"李清照","dynasty":"宋","dynastyCode":"song","content":"生当作人杰，死亦为鬼雄。\n至今思项羽，不肯过江东。","tags":["宋诗","爱国","咏史","小学必背","李清照"]},{"id":"song_060","title":"秋夜将晓出篱门迎凉有感","author":"陆游","dynasty":"宋","dynastyCode":"song","content":"三万里河东入海，五千仞岳上摩天。\n遗民泪尽胡尘里，南望王师又一年。","tags":["宋诗","爱国","悲愤","初中必背","陆游"]},{"id":"song_061","title":"卜算子·咏梅","author":"陆游","dynasty":"宋","dynastyCode":"song","content":"驿外断桥边，寂寞开无主。\n已是黄昏独自愁，更著风和雨。\n\n无意苦争春，一任群芳妒。\n零落成泥碾作尘，只有香如故。","tags":["宋词","咏物","梅花","初中必背","陆游"]},{"id":"song_062","title":"登飞来峰","author":"王安石","dynasty":"宋","dynastyCode":"song","content":"飞来山上千寻塔，闻说鸡鸣见日升。\n不畏浮云遮望眼，自缘身在最高层。","tags":["宋诗","哲理","壮志","初中必背","王安石"]},{"id":"song_063","title":"梅花","author":"王安石","dynasty":"宋","dynastyCode":"song","content":"墙角数枝梅，凌寒独自开。\n遥知不是雪，为有暗香来。","tags":["宋诗","咏物","梅花","小学必背","王安石"]},{"id":"song_064","title":"宿新市徐公店","author":"杨万里","dynasty":"宋","dynastyCode":"song","content":"篱落疏疏一径深，树头新绿未成阴。\n儿童急走追黄蝶，飞入菜花无处寻。","tags":["宋诗","田园","童趣","小学必背","杨万里"]},{"id":"song_065","title":"春日","author":"朱熹","dynasty":"宋","dynastyCode":"song","content":"胜日寻芳泗水滨，无边光景一时新。\n等闲识得东风面，万紫千红总是春。","tags":["宋诗","哲理","春天","小学必背","朱熹"]},{"id":"song_066","title":"生查子·元夕","author":"欧阳修","dynasty":"宋","dynastyCode":"song","content":"去年元夜时，花市灯如昼。\n月上柳梢头，人约黄昏后。\n\n今年元夜时，月与灯依旧。\n不见去年人，泪湿春衫袖。","tags":["宋词","婉约派","元宵","爱情","初中必背","欧阳修"]},{"id":"song_067","title":"蝶恋花·庭院深深深几许","author":"欧阳修","dynasty":"宋","dynastyCode":"song","content":"庭院深深深几许，杨柳堆烟，帘幕无重数。\n玉勒雕鞍游冶处，楼高不见章台路。\n\n雨横风狂三月暮，门掩黄昏，无计留春住。\n泪眼问花花不语，乱红飞过秋千去。","tags":["宋词","婉约派","伤春","闺怨","欧阳修"]},{"id":"song_068","title":"望海潮·东南形胜","author":"柳永","dynasty":"宋","dynastyCode":"song","content":"东南形胜，三吴都会，钱塘自古繁华。\n烟柳画桥，风帘翠幕，参差十万人家。\n云树绕堤沙，怒涛卷霜雪，天堑无涯。\n市列珠玑，户盈罗绮，竞豪奢。\n\n重湖叠巘清嘉，有三秋桂子，十里荷花。\n羌管弄晴，菱歌泛夜，嬉嬉钓叟莲娃。\n千骑拥高牙，乘醉听箫鼓，吟赏烟霞。\n异日图将好景，归去凤池夸。","tags":["宋词","婉约派","都市","名篇","柳永"]},{"id":"song_069","title":"小重山·昨夜寒蛩不住鸣","author":"岳飞","dynasty":"宋","dynastyCode":"song","content":"昨夜寒蛩不住鸣。惊回千里梦，已三更。\n起来独自绕阶行。人悄悄，帘外月胧明。\n\n白首为功名。旧山松竹老，阻归程。\n欲将心事付瑶琴。知音少，弦断有谁听？","tags":["宋词","爱国","悲愤","名篇","岳飞"]},{"id":"song_070","title":"虞美人·听雨","author":"蒋捷","dynasty":"宋","dynastyCode":"song","content":"少年听雨歌楼上，红烛昏罗帐。\n壮年听雨客舟中，江阔云低、断雁叫西风。\n\n而今听雨僧庐下，鬓已星星也。\n悲欢离合总无情，一任阶前、点滴到天明。","tags":["宋词","婉约派","感慨","名篇","蒋捷"]},{"id":"song_071","title":"青玉案·凌波不过横塘路","author":"贺铸","dynasty":"宋","dynastyCode":"song","content":"凌波不过横塘路，但目送、芳尘去。\n锦瑟华年谁与度？\n月桥花院，琐窗朱户，只有春知处。\n\n飞云冉冉蘅皋暮，彩笔新题断肠句。\n试问闲愁都几许？\n一川烟草，满城风絮，梅子黄时雨。","tags":["宋词","婉约派","愁绪","名篇","贺铸"]},{"id":"song_072","title":"卜算子·我住长江头","author":"李之仪","dynasty":"宋","dynastyCode":"song","content":"我住长江头，君住长江尾。\n日日思君不见君，共饮长江水。\n\n此水几时休，此恨何时已。\n只愿君心似我心，定不负相思意。","tags":["宋词","婉约派","爱情","名篇","李之仪"]},{"id":"song_073","title":"四时田园杂兴·其三十一","author":"范成大","dynasty":"宋","dynastyCode":"song","content":"昼出耘田夜绩麻，村庄儿女各当家。\n童孙未解供耕织，也傍桑阴学种瓜。","tags":["宋诗","田园","农事","小学必背","范成大"]},{"id":"song_074","title":"稚子弄冰","author":"杨万里","dynasty":"宋","dynastyCode":"song","content":"稚子金盆脱晓冰，彩丝穿取当银铮。\n敲成玉磬穿林响，忽作玻璃碎地声。","tags":["宋诗","童趣","冬天","小学必背","杨万里"]},{"id":"song_075","title":"临江仙·梦后楼台高锁","author":"晏几道","dynasty":"宋","dynastyCode":"song","content":"梦后楼台高锁，酒醒帘幕低垂。\n去年春恨却来时。\n落花人独立，微雨燕双飞。\n\n记得小苹初见，两重心字罗衣。\n琵琶弦上说相思。\n当时明月在，曾照彩云归。","tags":["宋词","婉约派","相思","名篇","晏几道"]},{"id":"song_076","title":"蝶恋花·春景","author":"苏轼","dynasty":"宋","dynastyCode":"song","content":"花褪残红青杏小。燕子飞时，绿水人家绕。\n枝上柳绵吹又少，天涯何处无芳草！\n\n墙里秋千墙外道。墙外行人，墙里佳人笑。\n笑渐不闻声渐悄，多情却被无情恼。","tags":["宋词","婉约派","伤春","苏轼"]},{"id":"song_077","title":"苏幕遮·碧云天","author":"范仲淹","dynasty":"宋","dynastyCode":"song","content":"碧云天，黄叶地，秋色连波，波上寒烟翠。\n山映斜阳天接水，芳草无情，更在斜阳外。\n\n黯乡魂，追旅思，夜夜除非，好梦留人睡。\n明月楼高休独倚，酒入愁肠，化作相思泪。","tags":["宋词","婉约派","思乡","秋景","范仲淹"]},{"id":"song_078","title":"客中初夏","author":"司马光","dynasty":"宋","dynastyCode":"song","content":"四月清和雨乍晴，南山当户转分明。\n更无柳絮因风起，惟有葵花向日倾。","tags":["宋诗","写景","夏天","名篇","司马光"]},{"id":"song_079","title":"蝶恋花·伫倚危楼风细细","author":"柳永","dynasty":"宋","dynastyCode":"song","content":"伫倚危楼风细细，望极春愁，黯黯生天际。草色烟光残照里，无言谁会凭阑意。拟把疏狂图一醉，对酒当歌，强乐还无味。衣带渐宽终不悔，为伊消得人憔悴。","tags":["宋词","婉约","爱情","名篇","柳永"]},{"id":"song_080","title":"踏莎行·郴州旅舍","author":"秦观","dynasty":"宋","dynastyCode":"song","content":"雾失楼台，月迷津渡，桃源望断无寻处。可堪孤馆闭春寒，杜鹃声里斜阳暮。驿寄梅花，鱼传尺素，砌成此恨无重数。郴江幸自绕郴山，为谁流下潇湘去？","tags":["宋词","婉约","羁旅","名篇","秦观"]},{"id":"song_083","title":"浣溪沙·簌簌衣巾落枣花","author":"苏轼","dynasty":"宋","dynastyCode":"song","content":"簌簌衣巾落枣花，村南村北响缫车，牛衣古柳卖黄瓜。酒困路长惟欲睡，日高人渴漫思茶，敲门试问野人家。","tags":["宋词","田园","苏轼"]},{"id":"sui_001","title":"春江花月夜","author":"张若虚","dynasty":"隋","dynastyCode":"sui","content":"春江潮水连海平，海上明月共潮生。\n滟滟随波千万里，何处春江无月明！\n江流宛转绕芳甸，月照花林皆似霰；\n空里流霜不觉飞，汀上白沙看不见。\n江天一色无纤尘，皎皎空中孤月轮。\n江畔何人初见月？江月何年初照人？\n人生代代无穷已，江月年年望相似。\n不知江月待何人，但见长江送流水。\n白云一片去悠悠，青枫浦上不胜愁。\n谁家今夜扁舟子？何处相思明月楼？\n可怜楼上月徘徊，应照离人妆镜台。\n玉户帘中卷不去，捣衣砧上拂还来。\n此时相望不相闻，愿逐月华流照君。\n鸿雁长飞光不度，鱼龙潜跃水成文。\n昨夜闲潭梦落花，可怜春半不还家。\n江水流春去欲尽，江潭落月复西斜。\n斜月沉沉藏海雾，碣石潇湘无限路。\n不知乘月几人归，落月摇情满江树。","tags":["唐诗先驱","孤篇压全唐","哲理","高中必背","张若虚"]},{"id":"sui_002","title":"送别","author":"佚名","dynasty":"隋","dynastyCode":"sui","content":"杨柳青青著地垂，杨花漫漫搅天飞。\n柳条折尽花飞尽，借问行人归不归？","tags":["送别","民歌","杨柳"]},{"id":"sui_003","title":"野望","author":"杨广","dynasty":"隋","dynastyCode":"sui","content":"寒鸦飞数点，流水绕孤村。斜阳欲落处，一望黯消魂。","tags":["写景","抒情","千古名句","杨广","意境"]},{"id":"sui_004","title":"人日思归","author":"薛道衡","dynasty":"隋","dynastyCode":"sui","content":"入春才七日，离家已二年。人归落雁后，思发在花前。","tags":["思乡","名句","薛道衡","五言绝句"]},{"id":"sui_005","title":"春江花月夜（其一）","author":"杨广","dynasty":"隋","dynastyCode":"sui","content":"暮江平不动，春花满正开。流波将月去，潮水带星来。","tags":["乐府","写景","春江花月夜之源","杨广"]},{"id":"sui_006","title":"落叶","author":"孔德绍","dynasty":"隋","dynastyCode":"sui","content":"早秋惊落叶，飘零似客心。翻飞未肯下，犹言惜故林。","tags":["咏物","托物言志","孔德绍","隋代名诗"]},{"id":"sui_007","title":"泛龙舟","author":"杨广","dynasty":"隋","dynastyCode":"sui","content":"舳舻千里泛归舟，言旋旧镇下扬州。借问扬州在何处，淮南江北海西头。","tags":["七言绝句","大运河","隋炀帝","咏史"]},{"id":"sui_008","title":"别宋常侍","author":"尹式","dynasty":"隋","dynastyCode":"sui","content":"游人杜陵北，送客汉川东。无论去与住，俱是一飘蓬。秋鬓含霜白，衰颜倚酒红。别有相思处，啼鸟杂夜风。","tags":["送别","五言律诗","律化","尹式"]},{"id":"sui_009","title":"山斋独坐赠薛内史","author":"杨素","dynasty":"隋","dynastyCode":"sui","content":"居山四望阻，风云竟朝夕。深溪横古树，空岩卧幽石。日出远岫明，鸟散空林寂。兰庭动幽气，竹室生虚白。落花入户飞，细草当阶积。桂酒徒盈樽，故人不在席。日暮山之幽，临风望羽客。","tags":["山水","五言古诗","杨素","隐逸"]},{"id":"tang_001","title":"静夜思","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"床前明月光，疑是地上霜。\n举头望明月，低头思故乡。","tags":["五言绝句","思乡","启蒙","小学必背"]},{"id":"tang_002","title":"将进酒","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"君不见黄河之水天上来，奔流到海不复回。\n君不见高堂明镜悲白发，朝如青丝暮成雪。\n人生得意须尽欢，莫使金樽空对月。\n天生我材必有用，千金散尽还复来。\n烹羊宰牛且为乐，会须一饮三百杯。\n\n岑夫子，丹丘生，将进酒，杯莫停。\n与君歌一曲，请君为我倾耳听。\n钟鼓馔玉不足贵，但愿长醉不复醒。\n古来圣贤皆寂寞，惟有饮者留其名。\n陈王昔时宴平乐，斗酒十千恣欢谑。\n主人何为言少钱，径须沽取对君酌。\n五花马，千金裘，\n呼儿将出换美酒，与尔同销万古愁。","tags":["乐府","豪放","名篇","高中必背","酒"]},{"id":"tang_003","title":"春望","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"国破山河在，城春草木深。\n感时花溅泪，恨别鸟惊心。\n烽火连三月，家书抵万金。\n白头搔更短，浑欲不胜簪。","tags":["五言律诗","爱国","沉郁","初中必背"]},{"id":"tang_004","title":"登高","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"风急天高猿啸哀，渚清沙白鸟飞回。\n无边落木萧萧下，不尽长江滚滚来。\n万里悲秋常作客，百年多病独登台。\n艰难苦恨繁霜鬓，潦倒新停浊酒杯。","tags":["七言律诗","沉郁","名篇","高中必背","秋"]},{"id":"tang_005","title":"赋得古原草送别","author":"白居易","dynasty":"唐","dynastyCode":"tang","content":"离离原上草，一岁一枯荣。\n野火烧不尽，春风吹又生。\n远芳侵古道，晴翠接荒城。\n又送王孙去，萋萋满别情。","tags":["五言律诗","送别","哲理","小学必背"]},{"id":"tang_006","title":"登鹳雀楼","author":"王之涣","dynasty":"唐","dynastyCode":"tang","content":"白日依山尽，黄河入海流。\n欲穷千里目，更上一层楼。","tags":["五言绝句","哲理","励志","小学必背"]},{"id":"tang_007","title":"出塞","author":"王昌龄","dynasty":"唐","dynastyCode":"tang","content":"秦时明月汉时关，万里长征人未还。\n但使龙城飞将在，不教胡马度阴山。","tags":["七言绝句","边塞","爱国","小学必背"]},{"id":"tang_008","title":"送元二使安西","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"渭城朝雨浥轻尘，客舍青青柳色新。\n劝君更尽一杯酒，西出阳关无故人。","tags":["七言绝句","送别","名篇","小学必背"]},{"id":"tang_009","title":"江雪","author":"柳宗元","dynasty":"唐","dynastyCode":"tang","content":"千山鸟飞绝，万径人踪灭。\n孤舟蓑笠翁，独钓寒江雪。","tags":["五言绝句","山水","孤独","小学必背","冬"]},{"id":"tang_010","title":"春晓","author":"孟浩然","dynasty":"唐","dynastyCode":"tang","content":"春眠不觉晓，处处闻啼鸟。\n夜来风雨声，花落知多少。","tags":["五言绝句","田园","春天","小学必背"]},{"id":"tang_011","title":"望岳","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"岱宗夫如何？齐鲁青未了。\n造化钟神秀，阴阳割昏晓。\n荡胸生曾云，决眦入归鸟。\n会当凌绝顶，一览众山小。","tags":["五言古诗","山水","励志","初中必背"]},{"id":"tang_012","title":"蜀道难","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"噫吁嚱，危乎高哉！\n蜀道之难，难于上青天！\n蚕丛及鱼凫，开国何茫然！\n尔来四万八千岁，不与秦塞通人烟。\n西当太白有鸟道，可以横绝峨眉巅。\n地崩山摧壮士死，然后天梯石栈相钩连。\n上有六龙回日之高标，下有冲波逆折之回川。\n黄鹤之飞尚不得过，猿猱欲度愁攀援。\n青泥何盘盘，百步九折萦岩峦。\n扪参历井仰胁息，以手抚膺坐长叹。\n\n问君西游何时还？畏途巉岩不可攀。\n但见悲鸟号古木，雄飞雌从绕林间。\n又闻子规啼夜月，愁空山。\n蜀道之难，难于上青天，使人听此凋朱颜！\n连峰去天不盈尺，枯松倒倚绝壁倚。\n飞湍瀑流争喧豗，砯崖转石万壑雷。\n其险也如此，嗟尔远道之人胡为乎来哉！\n\n剑阁峥嵘而崔嵬，一夫当关，万夫莫开。\n所守或匪亲，化为狼与豺。\n朝避猛虎，夕避长蛇；\n磨牙吮血，杀人如麻。\n锦城虽云乐，不如早还家。\n蜀道之难，难于上青天，侧身西望长咨嗟！","tags":["乐府","豪放","高中必背","名篇"]},{"id":"tang_013","title":"琵琶行","author":"白居易","dynasty":"唐","dynastyCode":"tang","content":"浔阳江头夜送客，枫叶荻花秋瑟瑟。\n主人下马客在船，举酒欲饮无管弦。\n醉不成欢惨将别，别时茫茫江浸月。\n忽闻水上琵琶声，主人忘归客不发。\n寻声暗问弹者谁，琵琶声停欲语迟。\n移船相近邀相见，添酒回灯重开宴。\n千呼万唤始出来，犹抱琵琶半遮面。\n转轴拨弦三两声，未成曲调先有情。\n弦弦掩抑声声思，似诉平生不得志。\n低眉信手续续弹，说尽心中无限事。\n轻拢慢捻抹复挑，初为《霓裳》后《六幺》。\n大弦嘈嘈如急雨，小弦切切如私语。\n嘈嘈切切错杂弹，大珠小珠落玉盘。\n间关莺语花底滑，幽咽泉流冰下难。\n冰泉冷涩弦凝绝，凝绝不通声暂歇。\n别有幽愁暗恨生，此时无声胜有声。\n银瓶乍破水浆迸，铁骑突出刀枪鸣。\n曲终收拨当心画，四弦一声如裂帛。\n东船西舫悄无言，唯见江心秋月白。\n沉吟放拨插弦中，整顿衣裳起敛容。\n自言本是京城女，家在虾蟆陵下住。\n十三学得琵琶成，名属教坊第一部。\n曲罢曾教善才服，妆成每被秋娘妒。\n五陵年少争缠头，一曲红绡不知数。\n钿头银篦击节碎，血色罗裙翻酒污。\n今年欢笑复明年，秋月春风等闲度。\n弟走从军阿姨死，暮去朝来颜色故。\n门前冷落鞍马稀，老大嫁作商人妇。\n商人重利轻别离，前月浮梁买茶去。\n去来江口守空船，绕船月明江水寒。\n夜深忽梦少年事，梦啼妆泪红阑干。\n我闻琵琶已叹息，又闻此语重唧唧。\n同是天涯沦落人，相逢何必曾相识！\n我从去年辞帝京，谪居卧病浔阳城。\n浔阳地僻无音乐，终岁不闻丝竹声。\n住近湓江地低湿，黄芦苦竹绕宅生。\n其间旦暮闻何物？杜鹃啼血猿哀鸣。\n春江花朝秋月夜，往往取酒还独倾。\n岂无山歌与村笛？呕哑嘲哳难为听。\n今夜闻君琵琶语，如听仙乐耳暂明。\n莫辞更坐弹一曲，为君翻作《琵琶行》。\n感我此言良久立，却坐促弦弦转急。\n凄凄不似向前声，满座重闻皆掩泣。\n座中泣下谁最多？江州司马青衫湿。","tags":["七言古诗","叙事","高中必背","贬谪"]},{"id":"tang_014","title":"黄鹤楼","author":"崔颢","dynasty":"唐","dynastyCode":"tang","content":"昔人已乘黄鹤去，此地空余黄鹤楼。\n黄鹤一去不复返，白云千载空悠悠。\n晴川历历汉阳树，芳草萋萋鹦鹉洲。\n日暮乡关何处是？烟波江上使人愁。","tags":["七言律诗","怀古","思乡","初中必背"]},{"id":"tang_015","title":"山居秋暝","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"空山新雨后，天气晚来秋。\n明月松间照，清泉石上流。\n竹喧归浣女，莲动下渔舟。\n随意春芳歇，王孙自可留。","tags":["五言律诗","山水","田园","高中必背"]},{"id":"tang_016","title":"无题·相见时难别亦难","author":"李商隐","dynasty":"唐","dynastyCode":"tang","content":"相见时难别亦难，东风无力百花残。\n春蚕到死丝方尽，蜡炬成灰泪始干。\n晓镜但愁云鬓改，夜吟应觉月光寒。\n蓬山此去无多路，青鸟殷勤为探看。","tags":["七言律诗","爱情","初中必背"]},{"id":"tang_017","title":"泊秦淮","author":"杜牧","dynasty":"唐","dynastyCode":"tang","content":"烟笼寒水月笼沙，夜泊秦淮近酒家。\n商女不知亡国恨，隔江犹唱后庭花。","tags":["七言绝句","咏史","忧国","初中必背"]},{"id":"tang_018","title":"行路难·其一","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"金樽清酒斗十千，玉盘珍羞直万钱。\n停杯投箸不能食，拔剑四顾心茫然。\n欲渡黄河冰塞川，将登太行雪满山。\n闲来垂钓碧溪上，忽复乘舟梦日边。\n行路难，行路难，多歧路，今安在？\n长风破浪会有时，直挂云帆济沧海。","tags":["乐府","豪放","初中必背"]},{"id":"tang_019","title":"酬乐天扬州初逢席上见赠","author":"刘禹锡","dynasty":"唐","dynastyCode":"tang","content":"巴山楚水凄凉地，二十三年弃置身。\n怀旧空吟闻笛赋，到乡翻似烂柯人。\n沉舟侧畔千帆过，病树前头万木春。\n今日听君歌一曲，暂凭杯酒长精神。","tags":["七言律诗","酬答","哲理","初中必背"]},{"id":"tang_020","title":"登幽州台歌","author":"陈子昂","dynasty":"唐","dynastyCode":"tang","content":"前不见古人，后不见来者。\n念天地之悠悠，独怆然而涕下！","tags":["古体诗","怀古","悲愤","初中必背"]},{"id":"tang_021","title":"使至塞上","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"单车欲问边，属国过居延。\n征蓬出汉塞，归雁入胡天。\n大漠孤烟直，长河落日圆。\n萧关逢候骑，都护在燕然。","tags":["五言律诗","边塞","名句","初中必背"]},{"id":"tang_022","title":"锦瑟","author":"李商隐","dynasty":"唐","dynastyCode":"tang","content":"锦瑟无端五十弦，一弦一柱思华年。\n庄生晓梦迷蝴蝶，望帝春心托杜鹃。\n沧海月明珠有泪，蓝田日暖玉生烟。\n此情可待成追忆，只是当时已惘然。","tags":["七言律诗","无题","高中必背","朦胧"]},{"id":"tang_023","title":"钱塘湖春行","author":"白居易","dynasty":"唐","dynastyCode":"tang","content":"孤山寺北贾亭西，水面初平云脚低。\n几处早莺争暖树，谁家新燕啄春泥。\n乱花渐欲迷人眼，浅草才能没马蹄。\n最爱湖东行不足，绿杨阴里白沙堤。","tags":["七言律诗","写景","春天","初中必背"]},{"id":"tang_024","title":"送杜少府之任蜀州","author":"王勃","dynasty":"唐","dynastyCode":"tang","content":"城阙辅三秦，风烟望五津。\n与君离别意，同是宦游人。\n海内存知己，天涯若比邻。\n无为在歧路，儿女共沾巾。","tags":["五言律诗","送别","初唐","初中必背"]},{"id":"tang_025","title":"茅屋为秋风所破歌","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"八月秋高风怒号，卷我屋上三重茅。\n茅飞渡江洒江郊，高者挂罥长林梢，下者飘转沉塘坳。\n南村群童欺我老无力，忍能对面为盗贼。\n公然抱茅入竹去，唇焦口燥呼不得，归来倚杖自叹息。\n俄顷风定云墨色，秋天漠漠向昏黑。\n布衾多年冷似铁，娇儿恶卧踏里裂。\n床头屋漏无干处，雨脚如麻未断绝。\n自经丧乱少睡眠，长夜沾湿何由彻！\n安得广厦千万间，大庇天下寒士俱欢颜！风雨不动安如山。\n呜呼！何时眼前突兀见此屋，吾庐独破受冻死亦足！","tags":["歌行体","忧国忧民","初中必背"]},{"id":"tang_026","title":"师说","author":"韩愈","dynasty":"唐","dynastyCode":"tang","content":"古之学者必有师。师者，所以传道受业解惑也。人非生而知之者，孰能无惑？惑而不从师，其为惑也，终不解矣。\n生乎吾前，其闻道也固先乎吾，吾从而师之；生乎吾后，其闻道也亦先乎吾，吾从而师之。吾师道也，夫庸知其年之先后生于吾乎？是故无贵无贱，无长无少，道之所存，师之所存也。\n嗟乎！师道之不传也久矣！欲人之无惑也难矣！古之圣人，其出人也远矣，犹且从师而问焉；今之众人，其下圣人也亦远矣，而耻学于师。是故圣益圣，愚益愚。圣人之所以为圣，愚人之所以为愚，其皆出于此乎？爱其子，择师而教之；于其身也，则耻师焉，惑矣。彼童子之师，授之书而习其句读者，非吾所谓传其道解其惑者也。句读之不知，惑之不解，或师焉，或不焉，小学而大遗，吾未见其明也。巫医乐师百工之人，不耻相师。士大夫之族，曰师曰弟子云者，则群聚而笑之。问之，则曰：'彼与彼年相若也，道相似也。位卑则足羞，官盛则近谀。'呜呼！师道之不复可知矣。巫医乐师百工之人，君子不齿，今其智乃反不能及，其可怪也欤！\n圣人无常师。孔子师郯子、苌弘、师襄、老聃。郯子之徒，其贤不及孔子。孔子曰：'三人行，则必有我师。'是故弟子不必不如师，师不必贤于弟子，闻道有先后，术业有专攻，如是而已。\n李氏子蟠，年十七，好古文，六艺经传皆通习之，不拘于时，学于余。余嘉其能行古道，作《师说》以贻之。","tags":["古文","议论","高中必背","韩愈"]},{"id":"tang_027","title":"阿房宫赋","author":"杜牧","dynasty":"唐","dynastyCode":"tang","content":"六王毕，四海一，蜀山兀，阿房出。覆压三百余里，隔离天日。骊山北构而西折，直走咸阳。二川溶溶，流入宫墙。五步一楼，十步一阁；廊腰缦回，檐牙高啄；各抱地势，钩心斗角。盘盘焉，囷囷焉，蜂房水涡，矗不知其几千万落。长桥卧波，未云何龙？复道行空，不霁何虹？高低冥迷，不知西东。歌台暖响，春光融融；舞殿冷袖，风雨凄凄。一日之内，一宫之间，而气候不齐。\n妃嫔媵嫱，王子皇孙，辞楼下殿，辇来于秦。朝歌夜弦，为秦宫人。明星荧荧，开妆镜也；绿云扰扰，梳晓鬟也；渭流涨腻，弃脂水也；烟斜雾横，焚椒兰也。雷霆乍惊，宫车过也；辘辘远听，杳不知其所之也。一肌一容，尽态极妍，缦立远视，而望幸焉。有不见者，三十六年。燕赵之收藏，韩魏之经营，齐楚之精英，几世几年，剽掠其人，倚叠如山。一旦不能有，输来其间。鼎铛玉石，金块珠砾，弃掷逦迤，秦人视之，亦不甚惜。\n嗟乎！一人之心，千万人之心也。秦爱纷奢，人亦念其家。奈何取之尽锱铢，用之如泥沙？使负栋之柱，多于南亩之农夫；架梁之椽，多于机上之工女；钉头磷磷，多于在庾之粟粒；瓦缝参差，多于周身之帛缕；直栏横槛，多于九土之城郭；管弦呕哑，多于市人之言语。使天下之人，不敢言而敢怒。独夫之心，日益骄固。戍卒叫，函谷举，楚人一炬，可怜焦土！\n呜呼！灭六国者六国也，非秦也；族秦者秦也，非天下也。嗟乎！使六国各爱其人，则足以拒秦；使秦复爱六国之人，则递三世可至万世而为君，谁得而族灭也？秦人不暇自哀，而后人哀之；后人哀之而不鉴之，亦使后人而复哀后人也。","tags":["赋","咏史","高中必背","杜牧"]},{"id":"tang_028","title":"陋室铭","author":"刘禹锡","dynasty":"唐","dynastyCode":"tang","content":"山不在高，有仙则名。水不在深，有龙则灵。斯是陋室，惟吾德馨。苔痕上阶绿，草色入帘青。谈笑有鸿儒，往来无白丁。可以调素琴，阅金经。无丝竹之乱耳，无案牍之劳形。南阳诸葛庐，西蜀子云亭。孔子云：何陋之有？","tags":["铭文","托物言志","初中必背","刘禹锡"]},{"id":"tang_029","title":"小石潭记","author":"柳宗元","dynasty":"唐","dynastyCode":"tang","content":"从小丘西行百二十步，隔篁竹，闻水声，如鸣珮环，心乐之。伐竹取道，下见小潭，水尤清冽。全石以为底，近岸，卷石底以出，为坻，为屿，为嵁，为岩。青树翠蔓，蒙络摇缀，参差披拂。\n潭中鱼可百许头，皆若空游无所依。日光下澈，影布石上，佁然不动；俶尔远逝，往来翕忽。似与游者相乐。\n潭西南而望，斗折蛇行，明灭可见。其岸势犬牙差互，不可知其源。\n坐潭上，四面竹树环合，寂寥无人，凄神寒骨，悄怆幽邃。以其境过清，不可久居，乃记之而去。\n同游者：吴武陵，龚古，余弟宗玄。隶而从者，崔氏二小生：曰恕己，曰奉壹。","tags":["游记","山水","初中必背","柳宗元"]},{"id":"tang_030","title":"马说","author":"韩愈","dynasty":"唐","dynastyCode":"tang","content":"世有伯乐，然后有千里马。千里马常有，而伯乐不常有。故虽有名马，祗辱于奴隶人之手，骈死于槽枥之间，不以千里称也。\n马之千里者，一食或尽粟一石。食马者不知其能千里而食也。是马也，虽有千里之能，食不饱，力不足，才美不外见，且欲与常马等不可得，安求其能千里也？\n策之不以其道，食之不能尽其材，鸣之而不能通其意，执策而临之，曰：'天下无马！'呜呼！其真无马邪？其真不知马也！","tags":["寓言","议论","初中必背","韩愈"]},{"id":"tang_031","title":"白雪歌送武判官归京","author":"岑参","dynasty":"唐","dynastyCode":"tang","content":"北风卷地白草折，胡天八月即飞雪。\n忽如一夜春风来，千树万树梨花开。\n散入珠帘湿罗幕，狐裘不暖锦衾薄。\n将军角弓不得控，都护铁衣冷难着。\n瀚海阑干百丈冰，愁云惨淡万里凝。\n中军置酒饮归客，胡琴琵琶与羌笛。\n纷纷暮雪下辕门，风掣红旗冻不翻。\n轮台东门送君去，去时雪满天山路。\n山回路转不见君，雪上空留马行处。","tags":["歌行体","边塞","送别","初中必背"]},{"id":"tang_032","title":"早发白帝城","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"朝辞白帝彩云间，千里江陵一日还。\n两岸猿声啼不住，轻舟已过万重山。","tags":["七言绝句","写景","快意","小学必背"]},{"id":"tang_033","title":"望天门山","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"天门中断楚江开，碧水东流至此回。\n两岸青山相对出，孤帆一片日边来。","tags":["七言绝句","山水","小学必背"]},{"id":"tang_034","title":"闻王昌龄左迁龙标遥有此寄","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"杨花落尽子规啼，闻道龙标过五溪。\n我寄愁心与明月，随君直到夜郎西。","tags":["七言绝句","送别","同情","初中必背"]},{"id":"tang_035","title":"游子吟","author":"孟郊","dynasty":"唐","dynastyCode":"tang","content":"慈母手中线，游子身上衣。\n临行密密缝，意恐迟迟归。\n谁言寸草心，报得三春晖。","tags":["五言古诗","母爱","名篇","小学必背"]},{"id":"tang_036","title":"卖炭翁","author":"白居易","dynasty":"唐","dynastyCode":"tang","content":"卖炭翁，伐薪烧炭南山中。\n满面尘灰烟火色，两鬓苍苍十指黑。\n卖炭得钱何所营？身上衣裳口中食。\n可怜身上衣正单，心忧炭贱愿天寒。\n夜来城外一尺雪，晓驾炭车辗冰辙。\n牛困人饥日已高，市南门外泥中歇。\n翩翩两骑来是谁？黄衣使者白衫儿。\n手把文书口称敕，回车叱牛牵向北。\n一车炭，千余斤，宫使驱将惜不得。\n半匹红纱一丈绫，系向牛头充炭直。","tags":["乐府","叙事","讽喻","初中必背"]},{"id":"tang_037","title":"赤壁","author":"杜牧","dynasty":"唐","dynastyCode":"tang","content":"折戟沉沙铁未销，自将磨洗认前朝。\n东风不与周郎便，铜雀春深锁二乔。","tags":["七言绝句","咏史","初中必背"]},{"id":"tang_038","title":"江南春","author":"杜牧","dynasty":"唐","dynastyCode":"tang","content":"千里莺啼绿映红，水村山郭酒旗风。\n南朝四百八十寺，多少楼台烟雨中。","tags":["七言绝句","写景","怀古","小学必背"]},{"id":"tang_039","title":"夜雨寄北","author":"李商隐","dynasty":"唐","dynastyCode":"tang","content":"君问归期未有期，巴山夜雨涨秋池。\n何当共剪西窗烛，却话巴山夜雨时。","tags":["七言绝句","思念","初中必背"]},{"id":"tang_040","title":"雁门太守行","author":"李贺","dynasty":"唐","dynastyCode":"tang","content":"黑云压城城欲摧，甲光向日金鳞开。\n角声满天秋色里，塞上燕脂凝夜紫。\n半卷红旗临易水，霜重鼓寒声不起。\n报君黄金台上意，提携玉龙为君死。","tags":["乐府","边塞","壮烈","初中必背"]},{"id":"tang_041","title":"梦游天姥吟留别","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"海客谈瀛洲，烟涛微茫信难求；\n越人语天姥，云霞明灭或可睹。\n天姥连天向天横，势拔五岳掩赤城。\n天台四万八千丈，对此欲倒东南倾。\n我欲因之梦吴越，一夜飞度镜湖月。\n湖月照我影，送我至剡溪。\n谢公宿处今尚在，渌水荡漾清猿啼。\n脚著谢公屐，身登青云梯。\n半壁见海日，空中闻天鸡。\n千岩万转路不定，迷花倚石忽已暝。\n熊咆龙吟殷岩泉，栗深林兮惊层巅。\n云青青兮欲雨，水澹澹兮生烟。\n列缺霹雳，丘峦崩摧。\n洞天石扉，訇然中开。\n青冥浩荡不见底，日月照耀金银台。\n霓为衣兮风为马，云之君兮纷纷而来下。\n虎鼓瑟兮鸾回车，仙之人兮列如麻。\n忽魂悸以魄动，恍惊起而长嗟。\n惟觉时之枕席，失向来之烟霞。\n世间行乐亦如此，古来万事东流水。\n别君去兮何时还？且放白鹿青崖间，须行即骑访名山。\n安能摧眉折腰事权贵，使我不得开心颜！","tags":["乐府","游仙","高中必背","名篇"]},{"id":"tang_042","title":"枫桥夜泊","author":"张继","dynasty":"唐","dynastyCode":"tang","content":"月落乌啼霜满天，江枫渔火对愁眠。\n姑苏城外寒山寺，夜半钟声到客船。","tags":["七言绝句","羁旅","名篇","小学必背"]},{"id":"tang_043","title":"回乡偶书","author":"贺知章","dynasty":"唐","dynastyCode":"tang","content":"少小离家老大回，乡音无改鬓毛衰。\n儿童相见不相识，笑问客从何处来。","tags":["七言绝句","思乡","小学必背"]},{"id":"tang_044","title":"咏柳","author":"贺知章","dynasty":"唐","dynastyCode":"tang","content":"碧玉妆成一树高，万条垂下绿丝绦。\n不知细叶谁裁出，二月春风似剪刀。","tags":["七言绝句","咏物","春天","小学必背"]},{"id":"tang_045","title":"凉州词","author":"王翰","dynasty":"唐","dynastyCode":"tang","content":"葡萄美酒夜光杯，欲饮琵琶马上催。\n醉卧沙场君莫笑，古来征战几人回？","tags":["七言绝句","边塞","豪迈","小学必背"]},{"id":"tang_046","title":"滁州西涧","author":"韦应物","dynasty":"唐","dynastyCode":"tang","content":"独怜幽草涧边生，上有黄鹂深树鸣。\n春潮带雨晚来急，野渡无人舟自横。","tags":["七言绝句","山水","恬淡","初中必背"]},{"id":"tang_047","title":"石壕吏","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"暮投石壕村，有吏夜捉人。老翁逾墙走，老妇出门看。\n吏呼一何怒！妇啼一何苦！\n听妇前致词：三男邺城戍。一男附书至，二男新战死。\n存者且偷生，死者长已矣！室中更无人，惟有乳下孙。\n有孙母未去，出入无完裙。老妪力虽衰，请从吏夜归，\n急应河阳役，犹得备晨炊。\n夜久语声绝，如闻泣幽咽。天明登前途，独与老翁别。","tags":["五言古诗","叙事","战乱","初中必背"]},{"id":"tang_048","title":"望庐山瀑布","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"日照香炉生紫烟，遥看瀑布挂前川。\n飞流直下三千尺，疑是银河落九天。","tags":["七言绝句","山水","夸张","小学必背"]},{"id":"tang_049","title":"春江花月夜","author":"张若虚","dynasty":"唐","dynastyCode":"tang","content":"春江潮水连海平，海上明月共潮生。\n滟滟随波千万里，何处春江无月明！\n江流宛转绕芳甸，月照花林皆似霰；\n空里流霜不觉飞，汀上白沙看不见。\n江天一色无纤尘，皎皎空中孤月轮。\n江畔何人初见月？江月何年初照人？\n人生代代无穷已，江月年年望相似。\n不知江月待何人，但见长江送流水。\n白云一片去悠悠，青枫浦上不胜愁。\n谁家今夜扁舟子？何处相思明月楼？\n可怜楼上月徘徊，应照离人妆镜台。\n玉户帘中卷不去，捣衣砧上拂还来。\n此时相望不相闻，愿逐月华流照君。\n鸿雁长飞光不度，鱼龙潜跃水成文。\n昨夜闲潭梦落花，可怜春半不还家。\n江水流春去欲尽，江潭落月复西斜。\n斜月沉沉藏海雾，碣石潇湘无限路。\n不知乘月几人归，落月摇情满江树。","tags":["乐府","孤篇压全唐","哲理","高中必背"]},{"id":"tang_050","title":"别董大","author":"高适","dynasty":"唐","dynastyCode":"tang","content":"千里黄云白日曛，北风吹雁雪纷纷。\n莫愁前路无知己，天下谁人不识君。","tags":["七言绝句","送别","豪迈","小学必背"]},{"id":"tang_051","title":"乐游原","author":"李商隐","dynasty":"唐","dynastyCode":"tang","content":"向晚意不适，驱车登古原。夕阳无限好，只是近黄昏。","tags":["五言绝句","哲理","小学必背","李商隐"]},{"id":"tang_052","title":"嫦娥","author":"李商隐","dynasty":"唐","dynastyCode":"tang","content":"云母屏风烛影深，长河渐落晓星沉。嫦娥应悔偷灵药，碧海青天夜夜心。","tags":["七言绝句","神话","名篇","李商隐"]},{"id":"tang_053","title":"贾生","author":"李商隐","dynasty":"唐","dynastyCode":"tang","content":"宣室求贤访逐臣，贾生才调更无伦。可怜夜半虚前席，不问苍生问鬼神。","tags":["七言绝句","咏史","李商隐"]},{"id":"tang_054","title":"九月九日忆山东兄弟","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"独在异乡为异客，每逢佳节倍思亲。遥知兄弟登高处，遍插茱萸少一人。","tags":["七言绝句","思乡","小学必背","王维"]},{"id":"tang_055","title":"相思","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"红豆生南国，春来发几枝。愿君多采撷，此物最相思。","tags":["五言绝句","爱情","名篇","王维"]},{"id":"tang_056","title":"终南别业","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"中岁颇好道，晚家南山陲。兴来每独往，胜事空自知。行到水穷处，坐看云起时。偶然值林叟，谈笑无还期。","tags":["五言律诗","山水","哲理","王维"]},{"id":"tang_057","title":"过华清宫绝句","author":"杜牧","dynasty":"唐","dynastyCode":"tang","content":"长安回望绣成堆，山顶千门次第开。一骑红尘妃子笑，无人知是荔枝来。","tags":["七言绝句","咏史","杜牧","小学必背"]},{"id":"tang_058","title":"山行","author":"杜牧","dynasty":"唐","dynastyCode":"tang","content":"远上寒山石径斜，白云深处有人家。停车坐爱枫林晚，霜叶红于二月花。","tags":["七言绝句","写景","小学必背","杜牧"]},{"id":"tang_059","title":"滕王阁诗","author":"王勃","dynasty":"唐","dynastyCode":"tang","content":"滕王高阁临江渚，佩玉鸣鸾罢歌舞。画栋朝飞南浦云，珠帘暮卷西山雨。闲云潭影日悠悠，物换星移几度秋。阁中帝子今何在？槛外长江空自流。","tags":["七言古诗","怀古","王勃","名篇"]},{"id":"tang_060","title":"乌衣巷","author":"刘禹锡","dynasty":"唐","dynastyCode":"tang","content":"朱雀桥边野草花，乌衣巷口夕阳斜。旧时王谢堂前燕，飞入寻常百姓家。","tags":["七言绝句","咏史","小学必背","刘禹锡"]},{"id":"tang_061","title":"竹枝词","author":"刘禹锡","dynasty":"唐","dynastyCode":"tang","content":"杨柳青青江水平，闻郎江上踏歌声。东边日出西边雨，道是无晴却有晴。","tags":["七言绝句","民歌","爱情","刘禹锡"]},{"id":"tang_062","title":"离思·其四","author":"元稹","dynasty":"唐","dynastyCode":"tang","content":"曾经沧海难为水，除却巫山不是云。取次花丛懒回顾，半缘修道半缘君。","tags":["七言绝句","爱情","名篇","元稹"]},{"id":"tang_063","title":"李凭箜篌引","author":"李贺","dynasty":"唐","dynastyCode":"tang","content":"吴丝蜀桐张高秋，空山凝云颓不流。江娥啼竹素女愁，李凭中国弹箜篌。昆山玉碎凤凰叫，芙蓉泣露香兰笑。十二门前融冷光，二十三丝动紫皇。女娲炼石补天处，石破天惊逗秋雨。梦入神山教神妪，老鱼跳波瘦蛟舞。吴质不眠倚桂树，露脚斜飞湿寒兔。","tags":["乐府","音乐","李贺","高中必背"]},{"id":"tang_064","title":"塞下曲","author":"卢纶","dynasty":"唐","dynastyCode":"tang","content":"月黑雁飞高，单于夜遁逃。欲将轻骑逐，大雪满弓刀。","tags":["五言绝句","边塞","小学必背"]},{"id":"tang_065","title":"逢雪宿芙蓉山主人","author":"刘长卿","dynasty":"唐","dynastyCode":"tang","content":"日暮苍山远，天寒白屋贫。柴门闻犬吠，风雪夜归人。","tags":["五言绝句","山水","小学必背"]},{"id":"tang_066","title":"悯农二首","author":"李绅","dynasty":"唐","dynastyCode":"tang","content":"春种一粒粟，秋收万颗子。四海无闲田，农夫犹饿死。锄禾日当午，汗滴禾下土。谁知盘中餐，粒粒皆辛苦。","tags":["五言古诗","讽喻","小学必背","李绅"]},{"id":"tang_067","title":"寻隐者不遇","author":"贾岛","dynasty":"唐","dynastyCode":"tang","content":"松下问童子，言师采药去。只在此山中，云深不知处。","tags":["五言绝句","隐逸","小学必背","贾岛"]},{"id":"tang_068","title":"蜀相","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"丞相祠堂何处寻？锦官城外柏森森。映阶碧草自春色，隔叶黄鹂空好音。三顾频频天下计，两朝开济老臣心。出师未捷身先死，长使英雄泪满襟。","tags":["七言律诗","咏史","高中必背","杜甫"]},{"id":"tang_069","title":"秋兴八首·其一","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"玉露凋伤枫树林，巫山巫峡气萧森。江间波浪兼天涌，塞上风云接地阴。丛菊两开他日泪，孤舟一系故园心。寒衣处处催刀尺，白帝城高急暮砧。","tags":["七言律诗","沉郁","杜甫","高中必背"]},{"id":"tang_070","title":"兵车行","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"车辚辚，马萧萧，行人弓箭各在腰。爷娘妻子走相送，尘埃不见咸阳桥。牵衣顿足拦道哭，哭声直上干云霄。道旁过者问行人，行人但云点行频。或从十五北防河，便至四十西营田。去时里正与裹头，归来头白还戍边。边庭流血成海水，武皇开边意未已。君不闻汉家山东二百州，千村万落生荆杞。纵有健妇把锄犁，禾生陇亩无东西。况复秦兵耐苦战，被驱不异犬与鸡。长者虽有问，役夫敢申恨？且如今年冬，未休关西卒。县官急索租，租税从何出？信知生男恶，反是生女好。生女犹得嫁比邻，生男埋没随百草。君不见青海头，古来白骨无人收。新鬼烦冤旧鬼哭，天阴雨湿声啾啾。","tags":["歌行体","战争","杜甫","高中必背"]},{"id":"tang_071","title":"登金陵凤凰台","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"凤凰台上凤凰游，凤去台空江自流。吴宫花草埋幽径，晋代衣冠成古丘。三山半落青天外，二水中分白鹭洲。总为浮云能蔽日，长安不见使人愁。","tags":["七言律诗","怀古","李白","名篇"]},{"id":"tang_072","title":"宣州谢朓楼饯别校书叔云","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"弃我去者，昨日之日不可留。乱我心者，今日之日多烦忧。长风万里送秋色，对此可以酣高楼。蓬莱文章建安骨，中间小谢又清发。俱怀逸兴壮思飞，欲上青天览明月。抽刀断水水更流，举杯销愁愁更愁。人生在世不称意，明朝散发弄扁舟。","tags":["古体诗","豪放","李白","高中必背"]},{"id":"tang_073","title":"凉州词·黄河远上","author":"王之涣","dynasty":"唐","dynastyCode":"tang","content":"黄河远上白云间，一片孤城万仞山。羌笛何须怨杨柳，春风不度玉门关。","tags":["七言绝句","边塞","小学必背","王之涣"]},{"id":"tang_074","title":"登柳州城楼寄漳汀封连四州","author":"柳宗元","dynasty":"唐","dynastyCode":"tang","content":"城上高楼接大荒，海天愁思正茫茫。惊风乱飐芙蓉水，密雨斜侵薜荔墙。岭树重遮千里目，江流曲似九回肠。共来百越文身地，犹自音书滞一乡。","tags":["七言律诗","贬谪","柳宗元","名篇"]},{"id":"tang_075","title":"望岳（西岳）","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"西岳崚嶒竦处尊，诸峰罗立似儿孙。安得仙人九节杖，拄到玉女洗头盆。车箱入谷无归路，箭栝通天有一门。稍待秋风凉冷后，高寻白帝问真源。","tags":["七言律诗","写景","杜甫"]},{"id":"tang_076","title":"丽人行","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"三月三日天气新，长安水边多丽人。态浓意远淑且真，肌理细腻骨肉匀。绣罗衣裳照暮春，蹙金孔雀银麒麟。头上何所有？翠微盍叶垂鬓唇。背后何所见？珠压腰衱稳称身。就中云幕椒房亲，赐名大国虢与秦。紫驼之峰出翠釜，水精之盘行素鳞。犀箸厌饫久未下，銮刀缕切空纷纶。黄门飞鞚不动尘，御厨络绎送八珍。箫鼓哀吟感鬼神，宾从杂遝实要津。后来鞍马何逡巡，当轩下马入锦茵。杨花雪落覆白蘋，青鸟飞去衔红巾。炙手可热势绝伦，慎莫近前丞相嗔！","tags":["歌行体","讽喻","名篇","杜甫"]},{"id":"tang_077","title":"春夜喜雨","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"好雨知时节，当春乃发生。随风潜入夜，润物细无声。野径云俱黑，江船火独明。晓看红湿处，花重锦官城。","tags":["五言律诗","写景","春天","杜甫","小学必背"]},{"id":"tang_078","title":"江南逢李龟年","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"岐王宅里寻常见，崔九堂前几度闻。正是江南好风景，落花时节又逢君。","tags":["七言绝句","感慨","杜甫","初中必背"]},{"id":"tang_079","title":"闻官军收河南河北","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"剑外忽传收蓟北，初闻涕泪满衣裳。却看妻子愁何在，漫卷诗书喜欲狂。白日放歌须纵酒，青春作伴好还乡。即从巴峡穿巫峡，便下襄阳向洛阳。","tags":["七言律诗","爱国","杜甫","高中必背"]},{"id":"tang_080","title":"旅夜书怀","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"细草微风岸，危樯独夜舟。星垂平野阔，月涌大江流。名岂文章著，官应老病休。飘飘何所似，天地一沙鸥。","tags":["五言律诗","感慨","杜甫","高中必背"]},{"id":"tang_081","title":"登岳阳楼","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"昔闻洞庭水，今上岳阳楼。吴楚东南坼，乾坤日夜浮。亲朋无一字，老病有孤舟。戎马关山北，凭轩涕泗流。","tags":["五言律诗","写景","感慨","杜甫","高中必背"]},{"id":"tang_082","title":"阁夜","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"岁暮阴阳催短景，天涯霜雪霁寒宵。五更鼓角声悲壮，三峡星河影动摇。野哭几家闻战伐，夷歌数处起渔樵。卧龙跃马终黄土，人事音书漫寂寥。","tags":["七言律诗","感慨","杜甫","高中必背"]},{"id":"tang_083","title":"咏怀古迹五首·其三","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"群山万壑赴荆门，生长明妃尚有村。一去紫台连朔漠，独留青冢向黄昏。画图省识春风面，环珮空归夜月魂。千载琵琶作胡语，分明怨恨曲中论。","tags":["七言律诗","咏史","杜甫","高中必背"]},{"id":"tang_084","title":"咏怀古迹五首·其五","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"诸葛大名垂宇宙，宗臣遗像肃清高。三分割据纡筹策，万古云霄一羽毛。伯仲之间见伊吕，指挥若定失萧曹。运移汉祚终难复，志决身歼军务劳。","tags":["七言律诗","咏史","杜甫","名篇"]},{"id":"tang_085","title":"羌村三首·其一","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"峥嵘赤云西，日脚下平地。柴门鸟雀噪，归客千里至。妻孥怪我在，惊定还拭泪。世乱遭飘荡，生还偶然遂。邻人满墙头，感叹亦歔欷。夜阑更秉烛，相对如梦寐。","tags":["五言古诗","叙事","杜甫","名篇"]},{"id":"tang_086","title":"新安吏","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"客行新安道，喧呼闻点兵。借问新安吏：县小更无丁？府帖昨夜下，次选中男行。中男绝短小，何以守王城？肥男有母送，瘦男独伶俜。白水暮东流，青山犹哭声。莫自使眼枯，收汝泪纵横。眼枯即见骨，天地终无情！","tags":["五言古诗","叙事","杜甫","名篇"]},{"id":"tang_087","title":"潼关吏","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"士卒何草草，筑城潼关道。大城铁不如，小城万丈余。借问潼关吏：修关还备胡？要我下马行，为我指山隅。连云列战格，飞鸟不能逾。胡来但自守，岂复忧西都。丈人视要处，窄狭容单车。艰难奋长戟，万古用一夫。哀哉桃林战，百万化为鱼。请嘱防关将，慎勿学哥舒！","tags":["五言古诗","叙事","杜甫","名篇"]},{"id":"tang_088","title":"新婚别","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"兔丝附蓬麻，引蔓故不长。嫁女与征夫，不如弃路旁。结发为妻子，席不暖君床。暮婚晨告别，无乃太匆忙。君行虽不远，守边赴河阳。妾身未分明，何以拜姑嫜？父母养我时，日夜令我藏。生女有所归，鸡狗亦得将。君今往死地，沉痛迫中肠。誓欲随君去，形势反苍黄。勿为新婚念，努力事戎行。","tags":["五言古诗","叙事","杜甫","名篇"]},{"id":"tang_089","title":"垂老别","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"四郊未宁静，垂老不得安。子孙阵亡尽，焉用身独完。投杖出门去，同行为辛酸。幸有牙齿存，所悲骨髓干。男儿既介胄，长揖别上官。老妻卧路啼，岁暮衣裳单。孰知是死别，且复伤其寒。此去必不归，还闻劝加餐。","tags":["五言古诗","叙事","杜甫","名篇"]},{"id":"tang_090","title":"无家别","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"寂寞天宝后，园庐但蒿藜。我里百余家，世乱各东西。存者无消息，死者为尘泥。贱子因阵败，归来寻旧蹊。久行见空巷，日瘦气惨凄。但对狐与狸，竖毛怒我啼。四邻何所有？一二老寡妻。","tags":["五言古诗","叙事","杜甫","名篇"]},{"id":"tang_091","title":"月夜忆舍弟","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"戍鼓断人行，边秋一雁声。露从今夜白，月是故乡明。有弟皆分散，无家问死生。寄书长不达，况乃未休兵。","tags":["五言律诗","思乡","杜甫","初中必背"]},{"id":"tang_092","title":"天末怀李白","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"凉风起天末，君子意如何。鸿雁几时到，江湖秋水多。文章憎命达，魑魅喜人过。应共冤魂语，投诗赠汨罗。","tags":["五言律诗","怀人","杜甫","名篇"]},{"id":"tang_093","title":"赠李白","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"秋来相顾尚飘蓬，未就丹砂愧葛洪。痛饮狂歌空度日，飞扬跋扈为谁雄。","tags":["七言绝句","赠别","杜甫","名篇"]},{"id":"tang_094","title":"春日忆李白","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"白也诗无敌，飘然思不群。清新庾开府，俊逸鲍参军。渭北春天树，江东日暮云。何时一樽酒，重与细论文。","tags":["五言律诗","怀人","杜甫","名篇"]},{"id":"tang_095","title":"戏为六绝句·其二","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"王杨卢骆当时体，轻薄为文哂未休。尔曹身与名俱灭，不废江河万古流。","tags":["七言绝句","评论","杜甫","名篇"]},{"id":"tang_096","title":"绝句四首·其三","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"两个黄鹂鸣翠柳，一行白鹭上青天。窗含西岭千秋雪，门泊东吴万里船。","tags":["七言绝句","写景","杜甫","小学必背"]},{"id":"tang_097","title":"江村","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"清江一曲抱村流，长夏江村事事幽。自去自来梁上燕，相亲相近水中鸥。老妻画纸为棋局，稚子敲针作钓钩。但有故人供禄米，微躯此外更何求。","tags":["七言律诗","闲适","杜甫","名篇"]},{"id":"tang_098","title":"客至","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"舍南舍北皆春水，但见群鸥日日来。花径不曾缘客扫，蓬门今始为君开。盘飧市远无兼味，樽酒家贫只旧醅。肯与邻翁相对饮，隔篱呼取尽余杯。","tags":["七言律诗","生活","杜甫","名篇"]},{"id":"tang_099","title":"江畔独步寻花七绝句·其六","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"黄四娘家花满蹊，千朵万朵压枝低。留连戏蝶时时舞，自在娇莺恰恰啼。","tags":["七言绝句","写景","春天","杜甫","小学必背"]},{"id":"tang_100","title":"赠花卿","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"锦城丝管日纷纷，半入江风半入云。此曲只应天上有，人间能得几回闻。","tags":["七言绝句","音乐","杜甫","小学必背"]},{"id":"tang_101","title":"前出塞九首·其六","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"挽弓当挽强，用箭当用长。射人先射马，擒贼先擒王。杀人亦有限，列国自有疆。苟能制侵陵，岂在多杀伤。","tags":["五言古诗","哲理","杜甫","名篇"]},{"id":"tang_102","title":"佳人","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"绝代有佳人，幽居在空谷。自云良家子，零落依草木。关中昔丧乱，兄弟遭杀戮。官高何足论，不得收骨肉。世情恶衰歇，万事随转烛。夫婿轻薄儿，新人美如玉。合昏尚知时，鸳鸯不独宿。但见新人笑，那闻旧人哭。在山泉水清，出山泉水浊。","tags":["五言古诗","叙事","杜甫","名篇"]},{"id":"tang_103","title":"宿府","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"清秋幕府井梧寒，独宿江城蜡炬残。永夜角声悲自语，中天月色好谁看。风尘荏苒音书绝，关塞萧条行路难。已忍伶俜十年事，强移栖息一枝安。","tags":["七言律诗","感慨","杜甫","名篇"]},{"id":"tang_104","title":"观公孙大娘弟子舞剑器行","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"昔有佳人公孙氏，一舞剑器动四方。观者如山色沮丧，天地为之久低昂。㸌如羿射九日落，矫如群帝骖龙翔。来如雷霆收震怒，罢如江海凝清光。","tags":["歌行体","音乐","杜甫","名篇"]},{"id":"tang_105","title":"缚鸡行","author":"杜甫","dynasty":"唐","dynastyCode":"tang","content":"小奴缚鸡向市卖，鸡被缚急相喧争。家中厌鸡食虫蚁，不知鸡卖还遭烹。虫鸡于人何厚薄，吾叱奴人解其缚。鸡虫得失无了时，注目寒江倚山阁。","tags":["七言古诗","哲理","杜甫","名篇"]},{"id":"tang_106","title":"古朗月行","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"小时不识月，呼作白玉盘。又疑瑶台镜，飞在青云端。仙人垂两足，桂树何团团。白兔捣药成，问言与谁餐。","tags":["五言古诗","童趣","李白","小学必背"]},{"id":"tang_107","title":"独坐敬亭山","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"众鸟高飞尽，孤云独去闲。相看两不厌，只有敬亭山。","tags":["五言绝句","山水","李白","小学必背"]},{"id":"tang_108","title":"赠汪伦","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"李白乘舟将欲行，忽闻岸上踏歌声。桃花潭水深千尺，不及汪伦送我情。","tags":["七言绝句","送别","李白","小学必背"]},{"id":"tang_109","title":"黄鹤楼送孟浩然之广陵","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"故人西辞黄鹤楼，烟花三月下扬州。孤帆远影碧空尽，唯见长江天际流。","tags":["七言绝句","送别","李白","小学必背"]},{"id":"tang_110","title":"渡荆门送别","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"渡远荆门外，来从楚国游。山随平野尽，江入大荒流。月下飞天镜，云生结海楼。仍怜故乡水，万里送行舟。","tags":["五言律诗","山水","李白","初中必背"]},{"id":"tang_111","title":"送友人","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"青山横北郭，白水绕东城。此地一为别，孤蓬万里征。浮云游子意，落日故人情。挥手自兹去，萧萧班马鸣。","tags":["五言律诗","送别","李白","初中必背"]},{"id":"tang_112","title":"子夜吴歌·秋歌","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"长安一片月，万户捣衣声。秋风吹不尽，总是玉关情。何日平胡虏，良人罢远征。","tags":["乐府","边塞","李白","名篇"]},{"id":"tang_113","title":"月下独酌四首·其一","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"花间一壶酒，独酌无相亲。举杯邀明月，对影成三人。月既不解饮，影徒随我身。暂伴月将影，行乐须及春。我歌月徘徊，我舞影零乱。醒时同交欢，醉后各分散。永结无情游，相期邈云汉。","tags":["五言古诗","饮酒","李白","高中必背"]},{"id":"tang_114","title":"塞下曲六首·其一","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"五月天山雪，无花只有寒。笛中闻折柳，春色未曾看。晓战随金鼓，宵眠抱玉鞍。愿将腰下剑，直为斩楼兰。","tags":["五言律诗","边塞","李白","名篇"]},{"id":"tang_115","title":"秋浦歌十七首·其十五","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"白发三千丈，缘愁似个长。不知明镜里，何处得秋霜。","tags":["五言绝句","感慨","李白","小学必背"]},{"id":"tang_116","title":"峨眉山月歌","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"峨眉山月半轮秋，影入平羌江水流。夜发清溪向三峡，思君不见下渝州。","tags":["七言绝句","山水","李白","初中必背"]},{"id":"tang_117","title":"春夜洛城闻笛","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"谁家玉笛暗飞声，散入春风满洛城。此夜曲中闻折柳，何人不起故园情。","tags":["七言绝句","思乡","李白","初中必背"]},{"id":"tang_118","title":"庐山谣寄卢侍御虚舟","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"我本楚狂人，凤歌笑孔丘。手持绿玉杖，朝别黄鹤楼。五岳寻仙不辞远，一生好入名山游。庐山秀出南斗傍，屏风九叠云锦张。影落明湖青黛光，金阙前开二峰长，银河倒挂三石梁。香炉瀑布遥相望，回崖沓嶂凌苍苍。","tags":["歌行体","山水","李白","名篇"]},{"id":"tang_119","title":"丁都护歌","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"云阳上征去，两岸饶商贾。吴牛喘月时，拖船一何苦。水浊不可饮，壶浆半成土。一唱都护歌，心摧泪如雨。万人系磐石，无由达江浒。君看石芒砀，掩泪悲千古。","tags":["乐府","同情","李白","名篇"]},{"id":"tang_120","title":"忆秦娥·箫声咽","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"箫声咽，秦娥梦断秦楼月。秦楼月，年年柳色，灞陵伤别。乐游原上清秋节，咸阳古道音尘绝。音尘绝，西风残照，汉家陵阙。","tags":["词","怀古","李白","名篇"]},{"id":"tang_121","title":"长相思·其一","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"长相思，在长安。络纬秋啼金井阑，微霜凄凄簟色寒。孤灯不明思欲绝，卷帷望月空长叹。美人如花隔云端。上有青冥之高天，下有渌水之波澜。天长地远魂飞苦，梦魂不到关山难。长相思，摧心肝！","tags":["乐府","爱情","李白","名篇"]},{"id":"tang_122","title":"下终南山过斛斯山人宿置酒","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"暮从碧山下，山月随人归。却顾所来径，苍苍横翠微。相携及田家，童稚开荆扉。绿竹入幽径，青萝拂行衣。欢言得所憩，美酒聊共挥。长歌吟松风，曲尽河星稀。我醉君复乐，陶然共忘机。","tags":["五言古诗","田园","李白","名篇"]},{"id":"tang_123","title":"登太白峰","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"太白与我语，为我开天关。举杯邀明月，对影成三友。太白何苍苍，星辰上森列。去天三百里，邈尔与世绝。","tags":["五言古诗","游仙","李白","名篇"]},{"id":"tang_124","title":"夜泊牛渚怀古","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"牛渚西江夜，青天无片云。登舟望秋月，空忆谢将军。余亦能高咏，斯人不可闻。明朝挂帆去，枫叶落纷纷。","tags":["五言律诗","怀古","李白","名篇"]},{"id":"tang_125","title":"与夏十二登岳阳楼","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"楼观岳阳尽，川迥洞庭开。雁引愁心去，山衔好月来。云间连下榻，天上接行杯。醉后凉风起，吹人舞袖回。","tags":["五言律诗","写景","李白","名篇"]},{"id":"tang_126","title":"访戴天山道士不遇","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"犬吠水声中，桃花带露浓。树深时见鹿，溪午不闻钟。野竹分青霭，飞泉挂碧峰。无人知所去，愁倚两三松。","tags":["五言律诗","山水","李白","名篇"]},{"id":"tang_127","title":"上李邕","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"大鹏一日同风起，扶摇直上九万里。假令风歇时下来，犹能簸却沧溟水。世人见我恒殊调，闻余大言皆冷笑。宣父犹能畏后生，丈夫未可轻年少。","tags":["七言古诗","言志","李白","名篇"]},{"id":"tang_128","title":"嘲鲁儒","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"鲁叟谈五经，白发死章句。问以经济策，茫如坠烟雾。足著远游履，首戴方山巾。缓步从直道，未行先起尘。秦家丞相府，不重褒衣人。君非叔孙通，与我本殊伦。时事且未达，归耕汶水滨。","tags":["五言古诗","讽喻","李白","名篇"]},{"id":"tang_129","title":"听蜀僧浚弹琴","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"蜀僧抱绿绮，西下峨眉峰。为我一挥手，如听万壑松。客心洗流水，余响入霜钟。不觉碧山暮，秋云暗几重。","tags":["五言律诗","音乐","李白","名篇"]},{"id":"tang_130","title":"沙丘城下寄杜甫","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"我来竟何事，高卧沙丘城。城边有古树，日夕连秋声。鲁酒不可醉，齐歌空复情。思君若汶水，浩荡寄南征。","tags":["五言古诗","怀人","李白","名篇"]},{"id":"tang_131","title":"金陵酒肆留别","author":"李白","dynasty":"唐","dynastyCode":"tang","content":"风吹柳花满店香，吴姬压酒劝客尝。金陵子弟来相送，欲行不行各尽觞。请君试问东流水，别意与之谁短长。","tags":["七言古诗","送别","李白","名篇"]},{"id":"tang_132","title":"鹿柴","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"空山不见人，但闻人语响。返景入深林，复照青苔上。","tags":["五言绝句","山水","王维","小学必背"]},{"id":"tang_133","title":"竹里馆","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"独坐幽篁里，弹琴复长啸。深林人不知，明月来相照。","tags":["五言绝句","闲适","王维","小学必背"]},{"id":"tang_134","title":"鸟鸣涧","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"人闲桂花落，夜静春山空。月出惊山鸟，时鸣春涧中。","tags":["五言绝句","山水","王维","小学必背"]},{"id":"tang_135","title":"画","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"远看山有色，近听水无声。春去花还在，人来鸟不惊。","tags":["五言绝句","题画","王维","小学必背"]},{"id":"tang_136","title":"山居即事","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"寂寞掩柴扉，苍茫对落晖。鹤巢松树遍，人访荜门稀。绿竹含新粉，红莲落故衣。渡头烟火起，处处采菱归。","tags":["五言律诗","山水","王维","名篇"]},{"id":"tang_137","title":"积雨辋川庄作","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"积雨空林烟火迟，蒸藜炊黍饷东菑。漠漠水田飞白鹭，阴阴夏木啭黄鹂。山中习静观朝槿，松下清斋折露葵。野老与人争席罢，海鸥何事更相疑。","tags":["七言律诗","山水","田园","王维","名篇"]},{"id":"tang_138","title":"青溪","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"言入黄花川，每逐青溪水。随山将万转，趣途无百里。声喧乱石中，色静深松里。漾漾泛菱荇，澄澄映葭苇。我心素已闲，清川澹如此。请留盘石上，垂钓将已矣。","tags":["五言古诗","山水","王维","名篇"]},{"id":"tang_139","title":"渭川田家","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"斜阳照墟落，穷巷牛羊归。野老念牧童，倚杖候荆扉。雉雊麦苗秀，蚕眠桑叶稀。田夫荷锄至，相见语依依。即此羡闲逸，怅然吟式微。","tags":["五言古诗","田园","王维","名篇"]},{"id":"tang_140","title":"汉江临眺","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"楚塞三湘接，荆门九派通。江流天地外，山色有无中。郡邑浮前浦，波澜动远空。襄阳好风日，留醉与山翁。","tags":["五言律诗","山水","王维","名篇"]},{"id":"tang_141","title":"观猎","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"风劲角弓鸣，将军猎渭城。草枯鹰眼疾，雪尽马蹄轻。忽过新丰市，还归细柳营。回看射雕处，千里暮云平。","tags":["五言律诗","边塞","王维","名篇"]},{"id":"tang_142","title":"酬张少府","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"晚年惟好静，万事不关心。自顾无长策，空知返旧林。松风吹解带，山月照弹琴。君问穷通理，渔歌入浦深。","tags":["五言律诗","隐逸","王维","名篇"]},{"id":"tang_143","title":"杂诗三首·其二","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"君自故乡来，应知故乡事。来日绮窗前，寒梅著花未？","tags":["五言绝句","思乡","王维","小学必背"]},{"id":"tang_144","title":"老将行","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"少年十五二十时，步行夺得胡马骑。射杀山中白额虎，肯数邺下黄须儿。一身转战三千里，一剑曾当百万师。汉兵奋迅如霹雳，虏骑崩腾畏蒺藜。卫青不败由天幸，李广无功缘数奇。自从弃置便衰朽，世事蹉跎成白首。","tags":["七言古诗","边塞","王维","名篇"]},{"id":"tang_145","title":"山中","author":"王维","dynasty":"唐","dynastyCode":"tang","content":"荆溪白石出，天寒红叶稀。山路元无雨，空翠湿人衣。","tags":["五言绝句","写景","王维","名篇"]},{"id":"tang_146","title":"春雨","author":"李商隐","dynasty":"唐","dynastyCode":"tang","content":"怅卧新春白袷衣，白门寥落意多违。红楼隔雨相望冷，珠箔飘灯独自归。远路应悲春晼晚，残宵犹得梦依稀。玉珰缄札何由达，万里云罗一雁飞。","tags":["七言律诗","爱情","李商隐","名篇"]},{"id":"tang_147","title":"隋宫","author":"李商隐","dynasty":"唐","dynastyCode":"tang","content":"乘兴南游不戒严，九重谁省谏书函。春风举国裁宫锦，半作障泥半作帆。","tags":["七言绝句","咏史","李商隐","名篇"]},{"id":"tang_148","title":"瑶池","author":"李商隐","dynasty":"唐","dynastyCode":"tang","content":"瑶池阿母绮窗开，黄竹歌声动地哀。八骏日行三万里，穆王何事不重来。","tags":["七言绝句","神话","李商隐","名篇"]},{"id":"tang_149","title":"蝉","author":"李商隐","dynasty":"唐","dynastyCode":"tang","content":"本以高难饱，徒劳恨费声。五更疏欲断，一树碧无情。薄宦梗犹泛，故园芜已平。烦君最相警，我亦举家清。","tags":["五言律诗","咏物","李商隐","名篇"]},{"id":"tang_150","title":"凉思","author":"李商隐","dynasty":"唐","dynastyCode":"tang","content":"客去波平槛，蝉休露满枝。永怀当此节，倚立自移时。北斗兼春远，南陵寓使迟。天涯占梦数，疑误有新知。","tags":["五言律诗","感怀","李商隐","名篇"]},{"id":"tang_151","title":"风雨","author":"李商隐","dynasty":"唐","dynastyCode":"tang","content":"凄凉宝剑篇，羁泊欲穷年。黄叶仍风雨，青楼自管弦。新知遭薄俗，旧好隔良缘。心断新丰酒，销愁斗几千。","tags":["五言律诗","感慨","李商隐","名篇"]},{"id":"tang_152","title":"登乐游原","author":"李商隐","dynasty":"唐","dynastyCode":"tang","content":"向晚意不适，驱车登古原。夕阳无限好，只是近黄昏。","tags":["五言绝句","哲理","李商隐","小学必背"]},{"id":"tang_153","title":"秋夕","author":"杜牧","dynasty":"唐","dynastyCode":"tang","content":"银烛秋光冷画屏，轻罗小扇扑流萤。天阶夜色凉如水，卧看牵牛织女星。","tags":["七言绝句","宫怨","杜牧","小学必背"]},{"id":"tang_154","title":"清明","author":"杜牧","dynasty":"唐","dynastyCode":"tang","content":"清明时节雨纷纷，路上行人欲断魂。借问酒家何处有，牧童遥指杏花村。","tags":["七言绝句","节日","杜牧","小学必背"]},{"id":"tang_155","title":"寄扬州韩绰判官","author":"杜牧","dynasty":"唐","dynastyCode":"tang","content":"青山隐隐水迢迢，秋尽江南草未凋。二十四桥明月夜，玉人何处教吹箫。","tags":["七言绝句","怀旧","杜牧","初中必背"]},{"id":"tang_156","title":"题乌江亭","author":"杜牧","dynasty":"唐","dynastyCode":"tang","content":"胜败兵家事不期，包羞忍耻是男儿。江东子弟多才俊，卷土重来未可知。","tags":["七言绝句","咏史","杜牧","名篇"]},{"id":"tang_157","title":"九日齐山登高","author":"杜牧","dynasty":"唐","dynastyCode":"tang","content":"江涵秋影雁初飞，与客携壶上翠微。尘世难逢开口笑，菊花须插满头归。但将酩酊酬佳节，不用登临恨落晖。古往今来只如此，牛山何必独沾衣。","tags":["七言律诗","重阳","杜牧","名篇"]},{"id":"tang_158","title":"大林寺桃花","author":"白居易","dynasty":"唐","dynastyCode":"tang","content":"人间四月芳菲尽，山寺桃花始盛开。长恨春归无觅处，不知转入此中来。","tags":["七言绝句","写景","白居易","小学必背"]},{"id":"tang_159","title":"暮江吟","author":"白居易","dynasty":"唐","dynastyCode":"tang","content":"一道残阳铺水中，半江瑟瑟半江红。可怜九月初三夜，露似真珠月似弓。","tags":["七言绝句","写景","白居易","小学必背"]},{"id":"tang_160","title":"问刘十九","author":"白居易","dynasty":"唐","dynastyCode":"tang","content":"绿蚁新醅酒，红泥小火炉。晚来天欲雪，能饮一杯无？","tags":["五言绝句","生活","白居易","名篇"]},{"id":"tang_161","title":"池上","author":"白居易","dynasty":"唐","dynastyCode":"tang","content":"小娒撑小艇，偷采白莲回。不解藏踪迹，浮萍一道开。","tags":["五言绝句","童趣","白居易","小学必背"]},{"id":"tang_162","title":"忆江南","author":"白居易","dynasty":"唐","dynastyCode":"tang","content":"江南好，风景旧曾谙。日出江花红胜火，春来江水绿如蓝。能不忆江南？","tags":["词","写景","白居易","小学必背"]},{"id":"tang_163","title":"观刈麦","author":"白居易","dynasty":"唐","dynastyCode":"tang","content":"田家少闲月，五月人倍忙。夜来南风起，小麦覆陇黄。妇姑荷箪食，童稚携壶浆。相随饷田去，丁壮在南冈。足蒸暑土气，背灼炎天光。力尽不知热，但惜夏日长。复有贫妇人，抱子在其旁。右手秉遗穗，左臂悬敝筐。听其相顾言，闻者为悲伤。家田输税尽，拾此充饥肠。今我何功德，曾不事农桑。吏禄三百石，岁晏有余粮。念此私自愧，尽日不能忘。","tags":["五言古诗","讽喻","白居易","初中必背"]},{"id":"tang_164","title":"邯郸冬至夜思家","author":"白居易","dynasty":"唐","dynastyCode":"tang","content":"邯郸驿里逢冬至，抱膝灯前影伴身。想得家中夜深坐，还应说着远行人。","tags":["七言绝句","思乡","白居易","名篇"]},{"id":"tang_165","title":"芙蓉楼送辛渐","author":"王昌龄","dynasty":"唐","dynastyCode":"tang","content":"寒雨连江夜入吴，平明送客楚山孤。洛阳亲友如相问，一片冰心在玉壶。","tags":["七言绝句","送别","王昌龄","小学必背"]},{"id":"tang_166","title":"采莲曲","author":"王昌龄","dynasty":"唐","dynastyCode":"tang","content":"荷叶罗裙一色裁，芙蓉向脸两边开。乱入池中看不见，闻歌始觉有人来。","tags":["七言绝句","写景","王昌龄","名篇"]},{"id":"tang_167","title":"从军行七首·其四","author":"王昌龄","dynasty":"唐","dynastyCode":"tang","content":"青海长云暗雪山，孤城遥望玉门关。黄沙百战穿金甲，不破楼兰终不还。","tags":["七言绝句","边塞","王昌龄","小学必背"]},{"id":"tang_168","title":"从军行七首·其二","author":"王昌龄","dynasty":"唐","dynastyCode":"tang","content":"琵琶起舞换新声，总是关山旧别情。撩乱边愁听不尽，高高秋月照长城。","tags":["七言绝句","边塞","王昌龄","名篇"]},{"id":"tang_169","title":"闺怨","author":"王昌龄","dynasty":"唐","dynastyCode":"tang","content":"闺中少妇不知愁，春日凝妆上翠楼。忽见陌头杨柳色，悔教夫婿觅封侯。","tags":["七言绝句","闺怨","王昌龄","名篇"]},{"id":"tang_170","title":"塞上曲","author":"王昌龄","dynasty":"唐","dynastyCode":"tang","content":"蝉鸣空桑林，八月萧关道。出塞入塞寒，处处黄芦草。从来幽并客，皆共尘沙老。莫学游侠儿，矜夸紫骝好。","tags":["五言古诗","边塞","王昌龄","名篇"]},{"id":"tang_171","title":"早春呈水部张十八员外","author":"韩愈","dynasty":"唐","dynastyCode":"tang","content":"天街小雨润如酥，草色遥看近却无。最是一年春好处，绝胜烟柳满皇都。","tags":["七言绝句","写景","春天","韩愈","小学必背"]},{"id":"tang_172","title":"左迁至蓝关示侄孙湘","author":"韩愈","dynasty":"唐","dynastyCode":"tang","content":"一封朝奏九重天，夕贬潮州路八千。欲为圣明除弊事，肯将衰朽惜残年。云横秦岭家何在？雪拥蓝关马不前。知汝远来应有意，好收吾骨瘴江边。","tags":["七言律诗","感慨","韩愈","高中必背"]},{"id":"tang_173","title":"进学解（节选）","author":"韩愈","dynasty":"唐","dynastyCode":"tang","content":"业精于勤，荒于嬉；行成于思，毁于随。方今圣贤相逢，治具毕张。拔去凶邪，登崇畯良。占小善者率以录，名一艺者无不庸。爬罗剔抉，刮垢磨光。盖有幸而获选，孰云多而不扬？诸生业患不能精，无患有司之不明；行患不能成，无患有司之不公。","tags":["散文","劝学","韩愈","名篇"]},{"id":"tang_174","title":"杂说·龙说","author":"韩愈","dynasty":"唐","dynastyCode":"tang","content":"龙嘘气成云，云固弗灵于龙也。然龙乘是气，茫洋穷乎玄间，薄日月，伏光景，感震电，神变化，水下土，汩陵谷，云亦灵怪矣哉！云，龙之所能使为灵也；若龙之灵，则非云之所能使为灵也。然龙弗得云，无以神其灵矣。失其所凭依，信不可欤！","tags":["散文","寓言","韩愈","名篇"]},{"id":"tang_175","title":"过故人庄","author":"孟浩然","dynasty":"唐","dynastyCode":"tang","content":"故人具鸡黍，邀我至田家。绿树村边合，青山郭外斜。开轩面场圃，把酒话桑麻。待到重阳日，还来就菊花。","tags":["五言律诗","田园","孟浩然","小学必背"]},{"id":"tang_176","title":"宿建德江","author":"孟浩然","dynasty":"唐","dynastyCode":"tang","content":"移舟泊烟渚，日暮客愁新。野旷天低树，江清月近人。","tags":["五言绝句","羁旅","孟浩然","小学必背"]},{"id":"tang_177","title":"望洞庭湖赠张丞相","author":"孟浩然","dynasty":"唐","dynastyCode":"tang","content":"八月湖水平，涵虚混太清。气蒸云梦泽，波撼岳阳城。欲济无舟楫，端居耻圣明。坐观垂钓者，徒有羡鱼情。","tags":["五言律诗","山水","孟浩然","初中必背"]},{"id":"tang_178","title":"岁暮归南山","author":"孟浩然","dynasty":"唐","dynastyCode":"tang","content":"北阙休上书，南山归敝庐。不才明主弃，多病故人疏。白发催年老，青阳逼岁除。永怀愁不寐，松月夜窗虚。","tags":["五言律诗","感慨","孟浩然","名篇"]},{"id":"tang_179","title":"留别王侍御维","author":"孟浩然","dynasty":"唐","dynastyCode":"tang","content":"寂寂竟何待，朝朝空自归。欲寻芳草去，惜与故人违。当路谁相假，知音世所稀。只应守寂寞，还掩故园扉。","tags":["五言律诗","送别","孟浩然","名篇"]},{"id":"tang_180","title":"次北固山下","author":"王湾","dynasty":"唐","dynastyCode":"tang","content":"客路青山外，行舟绿水前。潮平两岸阔，风正一帆悬。海日生残夜，江春入旧年。乡书何处达？归雁洛阳边。","tags":["五言律诗","羁旅","王湾","初中必背"]},{"id":"tang_181","title":"题破山寺后禅院","author":"常建","dynasty":"唐","dynastyCode":"tang","content":"清晨入古寺，初日照高林。曲径通幽处，禅房花木深。山光悦鸟性，潭影空人心。万籁此俱寂，但余钟磬音。","tags":["五言律诗","山水","常建","初中必背"]},{"id":"tang_182","title":"夜上受降城闻笛","author":"李益","dynasty":"唐","dynastyCode":"tang","content":"回乐峰前沙似雪，受降城外月如霜。不知何处吹芦管，一夜征人尽望乡。","tags":["七言绝句","边塞","李益","初中必背"]},{"id":"tang_183","title":"寒食","author":"韩翃","dynasty":"唐","dynastyCode":"tang","content":"春城无处不飞花，寒食东风御柳斜。日暮汉宫传蜡烛，轻烟散入五侯家。","tags":["七言绝句","节日","韩翃","名篇"]},{"id":"tang_184","title":"月夜","author":"刘方平","dynasty":"唐","dynastyCode":"tang","content":"更深月色半人家，北斗阑干南斗斜。今夜偏知春气暖，虫声新透绿窗纱。","tags":["七言绝句","写景","刘方平","名篇"]},{"id":"tang_185","title":"滕王阁序","author":"王勃","dynasty":"唐","dynastyCode":"tang","content":"豫章故郡，洪都新府。星分翼轸，地接衡庐。襟三江而带五湖，控蛮荆而引瓯越。物华天宝，龙光射牛斗之墟；人杰地灵，徐孺下陈蕃之榻。雄州雾列，俊采星驰。台隍枕夷夏之交，宾主尽东南之美。都督阎公之雅望，棨戟遥临；宇文新州之懿范，襜帷暂驻。十旬休假，胜友如云；千里逢迎，高朋满座。腾蛟起凤，孟学士之词宗；紫电青霜，王将军之武库。家君作宰，路出名区；童子何知，躬逢胜饯。\n\n时维九月，序属三秋。潦水尽而寒潭清，烟光凝而暮山紫。俨骖騑于上路，访风景于崇阿。临帝子之长洲，得天人之旧馆。层峦耸翠，上出重霄；飞阁流丹，下临无地。鹤汀凫渚，穷岛屿之萦回；桂殿兰宫，即冈峦之体势。\n\n披绣闼，俯雕甍，山原旷其盈视，川泽纡其骇瞩。闾阎扑地，钟鸣鼎食之家；舸舰弥津，青雀黄龙之舳。云销雨霁，彩彻区明。落霞与孤鹜齐飞，秋水共长天一色。渔舟唱晚，响穷彭蠡之滨；雁阵惊寒，声断衡阳之浦。\n\n遥襟甫畅，逸兴遄飞。爽籁发而清风生，纤歌凝而白云遏。睢园绿竹，气凌彭泽之樽；邺水朱华，光照临川之笔。四美具，二难并。穷睇眄于中天，极娱游于暇日。天高地迥，觉宇宙之无穷；兴尽悲来，识盈虚之有数。望长安于日下，目吴会于云间。地势极而南溟深，天柱高而北辰远。关山难越，谁悲失路之人？萍水相逢，尽是他乡之客。怀帝阍而不见，奉宣室以何年？\n\n嗟乎！时运不齐，命途多舛。冯唐易老，李广难封。屈贾谊于长沙，非无圣主；窜梁鸿于海曲，岂乏明时？所赖君子见机，达人知命。老当益壮，宁移白首之心？穷且益坚，不坠青云之志。酌贪泉而觉爽，处涸辙以犹欢。北海虽赊，扶摇可接；东隅已逝，桑榆非晚。孟尝高洁，空余报国之情；阮籍猖狂，岂效穷途之哭！\n\n勃，三尺微命，一介书生。无路请缨，等终军之弱冠；有怀投笔，慕宗悫之长风。舍簪笏于百龄，奉晨昏于万里。非谢家之宝树，接孟氏之芳邻。他日趋庭，叨陪鲤对；今兹捧袂，喜托龙门。杨意不逢，抚凌云而自惜；钟期既遇，奏流水以何惭？\n\n呜呼！胜地不常，盛筵难再；兰亭已矣，梓泽丘墟。临别赠言，幸承恩于伟饯；登高作赋，是所望于群公。敢竭鄙怀，恭疏短引；一言均赋，四韵俱成。请洒潘江，各倾陆海云尔。","tags":["古文","骈文","名篇","高中必背","滕王阁"]},{"id":"weijin_001","title":"归园田居·其一","author":"陶渊明","dynasty":"魏晋南北朝","dynastyCode":"weijin","content":"少无适俗韵，性本爱丘山。\n误落尘网中，一去三十年。\n羁鸟恋旧林，池鱼思故渊。\n开荒南野际，守拙归园田。\n方宅十余亩，草屋八九间。\n榆柳荫后檐，桃李罗堂前。\n暧暧远人村，依依墟里烟。\n狗吠深巷中，鸡鸣桑树颠。\n户庭无尘杂，虚室有余闲。\n久在樊笼里，复得返自然。","tags":["田园","隐逸","名篇","高中必背"]},{"id":"weijin_002","title":"饮酒·其五","author":"陶渊明","dynasty":"魏晋南北朝","dynastyCode":"weijin","content":"结庐在人境，而无车马喧。\n问君何能尔？心远地自偏。\n采菊东篱下，悠然见南山。\n山气日夕佳，飞鸟相与还。\n此中有真意，欲辨已忘言。","tags":["田园","隐逸","名篇","初中必背"]},{"id":"weijin_003","title":"桃花源记","author":"陶渊明","dynasty":"魏晋南北朝","dynastyCode":"weijin","content":"晋太元中，武陵人捕鱼为业。缘溪行，忘路之远近。忽逢桃花林，夹岸数百步，中无杂树，芳草鲜美，落英缤纷。渔人甚异之，复前行，欲穷其林。\n林尽水源，便得一山，山有小口，仿佛若有光。便舍船，从口入。初极狭，才通人。复行数十步，豁然开朗。土地平旷，屋舍俨然，有良田美池桑竹之属。阡陌交通，鸡犬相闻。其中往来种作，男女衣着，悉如外人。黄发垂髫，并怡然自乐。\n见渔人，乃大惊，问所从来。具答之。便要还家，设酒杀鸡作食。村中闻有此人，咸来问讯。自云先世避秦时乱，率妻子邑人来此绝境，不复出焉，遂与外人间隔。问今是何世，乃不知有汉，无论魏晋。此人一一为具言所闻，皆叹惋。余人各复延至其家，皆出酒食。停数日，辞去。此中人语云：不足为外人道也。\n既出，得其船，便扶向路，处处志之。及郡下，诣太守，说如此。太守即遣人随其往，寻向所志，遂迷，不复得路。\n南阳刘子骥，高尚士也，闻之，欣然规往。未果，寻病终。后遂无问津者。","tags":["散文","理想","名篇","初中必背"]},{"id":"weijin_004","title":"五柳先生传","author":"陶渊明","dynasty":"魏晋南北朝","dynastyCode":"weijin","content":"先生不知何许人也，亦不详其姓字，宅边有五柳树，因以为号焉。闲静少言，不慕荣利。好读书，不求甚解；每有会意，便欣然忘食。性嗜酒，家贫不能常得。亲旧知其如此，或置酒而招之；造饮辄尽，期在必醉。既醉而退，曾不吝情去留。环堵萧然，不蔽风日；短褐穿结，箪瓢屡空，晏如也。常著文章自娱，颇示己志。忘怀得失，以此自终。\n赞曰：黔娄之妻有言：不戚戚于贫贱，不汲汲于富贵。其言兹若人之俦乎？衔觞赋诗，以乐其志，无怀氏之民欤？葛天氏之民欤？","tags":["散文","隐逸","名篇","初中必背"]},{"id":"weijin_005","title":"归去来兮辞（节选）","author":"陶渊明","dynasty":"魏晋南北朝","dynastyCode":"weijin","content":"归去来兮，田园将芜胡不归？既自以心为形役，奚惆怅而独悲？悟已往之不谏，知来者之可追。实迷途其未远，觉今是而昨非。\n舟遥遥以轻飏，风飘飘而吹衣。问征夫以前路，恨晨光之熹微。乃瞻衡宇，载欣载奔。僮仆欢迎，稚子候门。三径就荒，松菊犹存。携幼入室，有酒盈樽。\n引壶觞以自酌，眄庭柯以怡颜。倚南窗以寄傲，审容膝之易安。园日涉以成趣，门虽设而常关。策扶老以流憩，时矫首而遐观。云无心以出岫，鸟倦飞而知还。景翳翳以将入，抚孤松而盘桓。","tags":["辞赋","归隐","高中必背","陶渊明"]},{"id":"weijin_006","title":"木兰诗","author":"北朝民歌","dynasty":"魏晋南北朝","dynastyCode":"weijin","content":"唧唧复唧唧，木兰当户织。不闻机杼声，唯闻女叹息。\n问女何所思，问女何所忆。女亦无所思，女亦无所忆。\n昨夜见军帖，可汗大点兵，军书十二卷，卷卷有爷名。\n阿爷无大儿，木兰无长兄，愿为市鞍马，从此替爷征。\n东市买骏马，西市买鞍鞯，南市买辔头，北市买长鞭。\n旦辞爷娘去，暮宿黄河边，不闻爷娘唤女声，但闻黄河流水鸣溅溅。\n旦辞黄河去，暮至黑山头，不闻爷娘唤女声，但闻燕山胡骑鸣啾啾。\n万里赴戎机，关山度若飞。朔气传金柝，寒光照铁衣。\n将军百战死，壮士十年归。\n归来见天子，天子坐明堂。策勋十二转，赏赐百千强。\n可汗问所欲，木兰不用尚书郎，愿驰千里足，送儿还故乡。\n爷娘闻女来，出郭相扶将；阿姊闻妹来，当户理红妆；\n小弟闻姊来，磨刀霍霍向猪羊。\n开我东阁门，坐我西阁床，脱我战时袍，著我旧时裳。\n当窗理云鬓，对镜帖花黄。出门看火伴，火伴皆惊忙：\n同行十二年，不知木兰是女郎。\n雄兔脚扑朔，雌兔眼迷离；双兔傍地走，安能辨我是雄雌？","tags":["乐府","叙事","女英雄","初中必背"]},{"id":"weijin_007","title":"敕勒歌","author":"北朝民歌","dynasty":"魏晋南北朝","dynastyCode":"weijin","content":"敕勒川，阴山下。\n天似穹庐，笼盖四野。\n天苍苍，野茫茫，\n风吹草低见牛羊。","tags":["民歌","边塞","小学必背","北朝"]},{"id":"weijin_008","title":"兰亭集序","author":"王羲之","dynasty":"魏晋南北朝","dynastyCode":"weijin","content":"永和九年，岁在癸丑，暮春之初，会于会稽山阴之兰亭，修禊事也。群贤毕至，少长咸集。此地有崇山峻岭，茂林修竹；又有清流激湍，映带左右，引以为流觞曲水，列坐其次。虽无丝竹管弦之盛，一觞一咏，亦足以畅叙幽情。\n是日也，天朗气清，惠风和畅。仰观宇宙之大，俯察品类之盛，所以游目骋怀，足以极视听之娱，信可乐也。\n夫人之相与，俯仰一世。或取诸怀抱，悟言一室之内；或因寄所托，放浪形骸之外。虽趣舍万殊，静躁不同，当其欣于所遇，暂得于己，快然自足，不知老之将至；及其所之既倦，情随事迁，感慨系之矣。向之所欣，俯仰之间，已为陈迹，犹不能不以之兴怀。况修短随化，终期于尽。古人云：死生亦大矣。岂不痛哉！\n每览昔人兴感之由，若合一契，未尝不临文嗟悼，不能喻之于怀。固知一死生为虚诞，齐彭殇为妄作。后之视今，亦犹今之视昔。悲夫！故列叙时人，录其所述。虽世殊事异，所以兴怀，其致一也。后之览者，亦将有感于斯文。","tags":["散文","哲理","书法","高中必背"]},{"id":"weijin_009","title":"陈情表","author":"李密","dynasty":"魏晋南北朝","dynastyCode":"weijin","content":"臣以险衅，夙遭闵凶。生孩六月，慈父见背；行年四岁，舅夺母志。祖母刘愍臣孤弱，躬亲抚养。臣少多疾病，九岁不行，零丁孤苦，至于成立。既无伯叔，终鲜兄弟，门衰祚薄，晚有儿息。外无期功强近之亲，内无应门五尺之僮，茕茕孑立，形影相吊。而刘夙婴疾病，常在床蓐，臣侍汤药，未曾废离。\n逮奉圣朝，沐浴清化。前太守臣逵察臣孝廉，后刺史臣荣举臣秀才。臣以供养无主，辞不赴命。诏书特下，拜臣郎中，寻蒙国恩，除臣洗马。猥以微贱，当侍东宫，非臣陨首所能上报。臣具以表闻，辞不就职。诏书切峻，责臣逋慢。郡县逼迫，催臣上道；州司临门，急于星火。臣欲奉诏奔驰，则刘病日笃；欲苟顺私情，则告诉不许。臣之进退，实为狼狈。\n伏惟圣朝以孝治天下，凡在故老，犹蒙矜育，况臣孤苦，特为尤甚。且臣少仕伪朝，历职郎署，本图宦达，不矜名节。今臣亡国贱俘，至微至陋，过蒙拔擢，宠命优渥，岂敢盘桓，有所希冀。但以刘日薄西山，气息奄奄，人命危浅，朝不虑夕。臣无祖母，无以至今日；祖母无臣，无以终余年。母孙二人，更相为命，是以区区不能废远。\n臣密今年四十有四，祖母刘今年九十有六，是臣尽节于陛下之日长，报养刘之日短也。乌鸟私情，愿乞终养。臣之辛苦，非独蜀之人士及二州牧伯所见明知，皇天后土实所共鉴。愿陛下矜愍愚诚，听臣微志，庶刘侥幸，保卒余年。臣生当陨首，死当结草。臣不胜犬马怖惧之情，谨拜表以闻。","tags":["散文","孝道","高中必背","李密"]},{"id":"weijin_010","title":"白马篇","author":"曹植","dynasty":"魏晋南北朝","dynastyCode":"weijin","content":"白马饰金羁，连翩西北驰。借问谁家子，幽并游侠儿。少小去乡邑，扬声沙漠垂。宿昔秉良弓，楛矢何参差。控弦破左的，右发摧月支。仰手接飞猱，俯身散马蹄。狡捷过猴猿，勇剽若豹螭。边城多警急，虏骑数迁移。羽檄从北来，厉马登高堤。长驱蹈匈奴，左顾凌鲜卑。弃身锋刃端，性命安可怀？父母且不顾，何言子与妻！名编壮士籍，不得中顾私。捐躯赴国难，视死忽如归！","tags":["乐府","游侠","名篇","曹植"]},{"id":"weijin_011","title":"七步诗","author":"曹植","dynasty":"魏晋南北朝","dynastyCode":"weijin","content":"煮豆燃豆萁，豆在釜中泣。本是同根生，相煎何太急？","tags":["五言诗","名篇","曹植"]},{"id":"weijin_012","title":"咏荆轲","author":"陶渊明","dynasty":"魏晋南北朝","dynastyCode":"weijin","content":"燕丹善养士，志在报强嬴。招集百夫良，岁暮得荆卿。君子死知己，提剑出燕京。素骥鸣广陌，慷慨送我行。雄发指危冠，猛气冲长缨。饮饯易水上，四座列群英。渐离击悲筑，宋意唱高声。萧萧哀风逝，澹澹寒波生。商音更流涕，羽奏壮士惊。心知去不归，且有后世名。登车何时顾，飞盖入秦庭。凌厉越万里，逶迤过千城。图穷事自至，豪主正怔营。惜哉剑术疏，奇功遂不成。其人虽已没，千载有馀情。","tags":["咏史","名篇","陶渊明"]},{"id":"weijin_013","title":"读山海经·其十","author":"陶渊明","dynasty":"魏晋南北朝","dynastyCode":"weijin","content":"精卫衔微木，将以填沧海。刑天舞干戚，猛志固常在。同物既无虑，化去不复悔。徒设在昔心，良辰讵可待。","tags":["咏史","名篇","陶渊明"]},{"id":"weijin_014","title":"西洲曲","author":"南朝民歌","dynasty":"魏晋南北朝","dynastyCode":"weijin","content":"忆梅下西洲，折梅寄江北。单衫杏子红，双鬓鸦雏色。西洲在何处？两桨桥头渡。日暮伯劳飞，风吹乌臼树。树下即门前，门中露翠钿。开门郎不至，出门采红莲。采莲南塘秋，莲花过人头。低头弄莲子，莲子清如水。置莲怀袖中，莲心彻底红。忆郎郎不至，仰首望飞鸿。鸿飞满西洲，望郎上青楼。楼高望不见，尽日栏杆头。栏杆十二曲，垂手明如玉。卷帘天自高，海水摇空绿。海水梦悠悠，君愁我亦愁。南风知我意，吹梦到西洲。","tags":["民歌","爱情","名篇","南朝"]},{"id":"xiandai_001","title":"再别康桥","author":"徐志摩","dynasty":"近现代","dynastyCode":"xiandai","content":"轻轻的我走了，\n正如我轻轻的来；\n我轻轻的招手，\n作别西天的云彩。\n\n那河畔的金柳，\n是夕阳中的新娘；\n波光里的艳影，\n在我的心头荡漾。\n\n软泥上的青荇，\n油油的在水底招摇；\n在康河的柔波里，\n我甘心做一条水草！\n\n那榆荫下的一潭，\n不是清泉，是天上虹；\n揉碎在浮藻间，\n沉淀着彩虹似的梦。\n\n寻梦？撑一支长篙，\n向青草更青处漫溯；\n满载一船星辉，\n在星辉斑斓里放歌。\n\n但我不能放歌，\n悄悄是别离的笙箫；\n夏虫也为我沉默，\n沉默是今晚的康桥！\n\n悄悄的我走了，\n正如我悄悄的来；\n我挥一挥衣袖，\n不带走一片云彩。","tags":["现代诗","新月派","名篇","高中必背","徐志摩"]},{"id":"xiandai_002","title":"雨巷","author":"戴望舒","dynasty":"近现代","dynastyCode":"xiandai","content":"撑着油纸伞，独自\n彷徨在悠长、悠长\n又寂寥的雨巷\n我希望逢着\n一个丁香一样地\n结着愁怨的姑娘\n\n她是有\n丁香一样的颜色\n丁香一样的芬芳\n丁香一样的忧愁\n在雨中哀怨\n哀怨又彷徨\n\n她彷徨在这寂寥的雨巷\n撑着油纸伞\n像我一样\n像我一样地\n默默彳亍着\n冷漠、凄清，又惆怅\n\n她默默地走近\n走近，又投出\n太息一般的眼光\n她飘过\n像梦一般地\n像梦一般地凄婉迷茫\n\n像梦中飘过\n一枝丁香地\n我身旁飘过这女郎\n她静默地远了，远了\n到了颓圮的篱墙\n走尽这雨巷\n\n在雨的哀曲里\n消了她的颜色\n散了她的芬芳\n消散了，甚至她的\n太息般的眼光\n丁香般的惆怅\n\n撑着油纸伞，独自\n彷徨在悠长、悠长\n又寂寥的雨巷\n我希望飘过\n一个丁香一样地\n结着愁怨的姑娘","tags":["现代诗","象征主义","名篇","高中必背","戴望舒"]},{"id":"xiandai_003","title":"面朝大海，春暖花开","author":"海子","dynasty":"近现代","dynastyCode":"xiandai","content":"从明天起，做一个幸福的人\n喂马，劈柴，周游世界\n从明天起，关心粮食和蔬菜\n我有一所房子，面朝大海，春暖花开\n\n从明天起，和每一个亲人通信\n告诉他们我的幸福\n那幸福的闪电告诉我的\n我将告诉每一个人\n\n给每一条河每一座山取一个温暖的名字\n陌生人，我也为你祝福\n愿你有一个灿烂的前程\n愿你有情人终成眷属\n愿你在尘世获得幸福\n我只愿面朝大海，春暖花开","tags":["现代诗","抒情","名篇","海子"]},{"id":"xiandai_004","title":"乡愁","author":"余光中","dynasty":"近现代","dynastyCode":"xiandai","content":"小时候\n乡愁是一枚小小的邮票\n我在这头\n母亲在那头\n\n长大后\n乡愁是一张窄窄的船票\n我在这头\n新娘在那头\n\n后来啊\n乡愁是一方矮矮的坟墓\n我在外头\n母亲在里头\n\n而现在\n乡愁是一湾浅浅的海峡\n我在这头\n大陆在那头","tags":["现代诗","思乡","名篇","初中必背","余光中"]},{"id":"xiandai_005","title":"我爱这土地","author":"艾青","dynasty":"近现代","dynastyCode":"xiandai","content":"假如我是一只鸟，\n我也应该用嘶哑的喉咙歌唱：\n这被暴风雨所打击着的土地，\n这永远汹涌着我们的悲愤的河流，\n这无止息地吹刮着的激怒的风，\n和那来自林间的无比温柔的黎明……\n——然后我死了，\n连羽毛也腐烂在土地里面。\n\n为什么我的眼里常含泪水？\n因为我对这土地爱得深沉……","tags":["现代诗","爱国","名篇","初中必背","艾青"]},{"id":"xiandai_006","title":"天狗（节选）","author":"郭沫若","dynasty":"近现代","dynastyCode":"xiandai","content":"我是一条天狗呀！\n我把月来吞了，\n我把日来吞了，\n我把一切的星球来吞了，\n我把全宇宙来吞了。\n我便是我了！\n\n我是月底光，\n我是日底光，\n我是一切星球底光，\n我是X光线底光，\n我是全宇宙底Energy底总量！\n\n我飞奔，\n我狂叫，\n我燃烧。\n我如烈火一样地燃烧！\n我如大海一样地狂叫！\n我如电气一样地飞跑！\n\n我剥我的皮，\n我食我的肉，\n我吸我的血，\n我啮我的心肝，\n我在我神经上飞跑，\n我在我脊髓上飞跑，\n我在我脑筋上飞跑。\n\n我便是我呀！\n我的我要爆了！","tags":["现代诗","郭沫若","创造社","狂飙突进","名篇"]},{"id":"xiandai_007","title":"断章","author":"卞之琳","dynasty":"近现代","dynastyCode":"xiandai","content":"你站在桥上看风景，\n看风景的人在楼上看你。\n\n明月装饰了你的窗子，\n你装饰了别人的梦。","tags":["现代诗","卞之琳","哲理","名篇","新月派"]},{"id":"xiandai_008","title":"错误","author":"郑愁予","dynasty":"近现代","dynastyCode":"xiandai","content":"我打江南走过\n那等在季节里的容颜如莲花的开落\n\n东风不来，三月的柳絮不飞\n你的心如小小的寂寞的城\n恰若青石的街道向晚\n跫音不响，三月的春帷不揭\n你的心是小小的窗扉紧掩\n\n我达达的马蹄是美丽的错误\n我不是归人，是个过客……","tags":["现代诗","郑愁予","台湾","名篇","抒情"]},{"id":"xiandai_009","title":"致橡树","author":"舒婷","dynasty":"近现代","dynastyCode":"xiandai","content":"我如果爱你——\n绝不像攀援的凌霄花\n借你的高枝炫耀自己；\n我如果爱你——\n绝不学痴情的鸟儿\n为绿荫重复单调的歌曲；\n也不止像泉源\n常年送来清凉的慰藉；\n也不止像险峰\n增加你的高度，衬托你的威仪。\n甚至日光，\n甚至春雨。\n不，这些都还不够！\n我必须是你近旁的一株木棉，\n作为树的形象和你站在一起。\n根，紧握在地下；\n叶，相触在云里。\n每一阵风过，\n我们都互相致意，\n但没有人\n听懂我们的言语。\n你有你的铜枝铁干\n像刀，像剑，也像戟；\n我有我红硕的花朵\n像沉重的叹息，\n又像英勇的火炬。\n我们分担寒潮、风雷、霹雳；\n我们共享雾霭、流岚、虹霓。\n仿佛永远分离，\n却又终身相依。\n这才是伟大的爱情，\n坚贞就在这里：\n爱——\n不仅爱你伟岸的身躯，\n也爱你坚持的位置，足下的土地。","tags":["现代诗","舒婷","朦胧诗","爱情","名篇","高中必背"]},{"id":"xiandai_010","title":"一代人","author":"顾城","dynasty":"近现代","dynastyCode":"xiandai","content":"黑夜给了我黑色的眼睛\n我却用它寻找光明","tags":["现代诗","顾城","朦胧诗","名篇","哲理"]},{"id":"xiandai_011","title":"回答","author":"北岛","dynasty":"近现代","dynastyCode":"xiandai","content":"卑鄙是卑鄙者的通行证，\n高尚是高尚者的墓志铭。\n看吧，在那镀金的天空中，\n飘满了死者弯曲的倒影。\n\n冰川纪过去了，\n为什么到处都是冰凌？\n好望角发现了，\n为什么死海里千帆相竞？\n\n我来到这个世界上，\n只带着纸、绳索和身影，\n为了在审判前，\n宣读那些被判决的声音：\n\n告诉你吧，世界\n我——不——相——信！\n纵使你脚下有一千名挑战者，\n那就把我算作第一千零一名。\n\n我不相信天是蓝的，\n我不相信雷的回声，\n我不相信梦是假的，\n我不相信死无报应。\n\n如果海洋注定要决堤，\n就让所有的苦水都注入我心中；\n如果陆地注定要上升，\n就让人类重新选择生存的峰顶。\n\n新的转机和闪闪星斗，\n正在缀满没有遮拦的天空。\n那是五千年的象形文字，\n那是未来人们凝视的眼睛。","tags":["现代诗","北岛","朦胧诗","名篇","反思"]},{"id":"xiandai_012","title":"相信未来","author":"食指","dynasty":"近现代","dynastyCode":"xiandai","content":"当蜘蛛网无情地查封了我的炉台\n当灰烬的余烟叹息着贫困的悲哀\n我依然固执地铺平失望的灰烬\n用美丽的雪花写下：相信未来\n\n当我的紫葡萄化为深秋的露水\n当我的鲜花依偎在别人的情怀\n我依然固执地用凝露的枯藤\n在凄凉的大地上写下：相信未来\n\n我要用手指那涌向天边的排浪\n我要用手掌那托住太阳的大海\n摇曳着曙光那枝温暖漂亮的笔杆\n用孩子的笔体写下：相信未来\n\n我之所以坚定地相信未来\n是我相信未来人们的眼睛\n她有拨开历史风尘的睫毛\n她有看透岁月篇章的瞳孔\n\n不管人们对于我们腐烂的皮肉\n那些迷途的惆怅、失败的苦痛\n是寄予感动的热泪、深切的同情\n还是给以轻蔑的微笑、辛辣的嘲讽\n\n我坚信人们对于我们的脊骨\n那无数次的探索、迷途、失败和成功\n一定会给予热情、客观、公正的评定\n是的，我焦急地等待着他们的评定\n\n朋友，坚定地相信未来吧\n相信不屈不挠的努力\n相信战胜死亡的年轻\n相信未来，热爱生命","tags":["现代诗","食指","名篇","励志","经典"]},{"id":"xiandai_013","title":"七子之歌·澳门","author":"闻一多","dynasty":"近现代","dynastyCode":"xiandai","content":"你可知妈港不是我的真名姓？\n我离开你的襁褓太久了，母亲！\n但是他们掳去的是我的肉体，\n你依然保管着我内心的灵魂。\n\n三百年来梦寐不忘的生母啊！\n请叫儿的乳名，叫我一声「澳门」！\n母亲！我要回来，母亲！","tags":["现代诗","闻一多","爱国","名篇","七子之歌"]},{"id":"xiandai_014","title":"一棵开花的树","author":"席慕蓉","dynasty":"近现代","dynastyCode":"xiandai","content":"如何让你遇见我\n在我最美丽的时刻\n为这\n我已在佛前求了五百年\n求佛让我们结一段尘缘\n佛于是把我化做一棵树\n长在你必经的路旁\n\n阳光下\n慎重地开满了花\n朵朵都是我前世的盼望\n\n当你走近\n请你细听\n那颤抖的叶\n是我等待的热情\n\n而当你终于无视地走过\n在你身后落了一地的\n朋友啊\n那不是花瓣\n那是我凋零的心","tags":["现代诗","席慕蓉","爱情","名篇","台湾"]},{"id":"xiandai_015","title":"热爱生命","author":"汪国真","dynasty":"近现代","dynastyCode":"xiandai","content":"我不去想是否能够成功\n既然选择了远方\n便只顾风雨兼程\n\n我不去想能否赢得爱情\n既然钟情于玫瑰\n就勇敢地吐露真诚\n\n我不去想身后会不会袭来寒风冷雨\n既然目标是地平线\n留给世界的只能是背影\n\n我不去想未来是平坦还是泥泞\n只要热爱生命\n一切，都在意料之中","tags":["现代诗","汪国真","励志","名篇","哲理"]},{"id":"xiandai_016","title":"沁园春·长沙","author":"毛泽东","dynasty":"近现代","dynastyCode":"xiandai","content":"独立寒秋，湘江北去，橘子洲头。看万山红遍，层林尽染；漫江碧透，百舸争流。鹰击长空，鱼翔浅底，万类霜天竞自由。怅寥廓，问苍茫大地，谁主沉浮？携来百侣曾游，忆往昔峥嵘岁月稠。恰同学少年，风华正茂；书生意气，挥斥方遒。指点江山，激扬文字，粪土当年万户侯。曾记否，到中流击水，浪遏飞舟？","tags":["现代诗","豪放","名篇","高中必背","毛泽东"]},{"id":"xiandai_017","title":"沁园春·雪","author":"毛泽东","dynasty":"近现代","dynastyCode":"xiandai","content":"北国风光，千里冰封，万里雪飘。望长城内外，惟余莽莽；大河上下，顿失滔滔。山舞银蛇，原驰蜡象，欲与天公试比高。须晴日，看红装素裹，分外妖娆。江山如此多娇，引无数英雄竞折腰。惜秦皇汉武，略输文采；唐宗宋祖，稍逊风骚。一代天骄，成吉思汗，只识弯弓射大雕。俱往矣，数风流人物，还看今朝。","tags":["现代诗","豪放","名篇","初中必背","毛泽东"]},{"id":"xiandai_018","title":"有的人","author":"臧克家","dynasty":"近现代","dynastyCode":"xiandai","content":"有的人活着，他已经死了；有的人死了，他还活着。有的人骑在人民头上：呵，我多伟大！有的人俯下身子给人民当牛马。有的人把名字刻入石头，想不朽；有的人情愿作野草，等着地下的火烧。有的人他活着别人就不能活；有的人他活着为了多数人更好地活。骑在人民头上的人民把他摔垮；给人民作牛马的人民永远记住他！把名字刻入石头的名字比尸首烂得更早；只要春风吹到的地方到处是青青的野草。他活着别人就不能活的人，他的下场可以看到；他活着为了多数人更好地活的人，群众把他抬举得很高，很高。","tags":["现代诗","哲理","名篇","臧克家"]},{"id":"xianqin_001","title":"关雎","author":"《诗经》","dynasty":"先秦","dynastyCode":"xianqin","content":"关关雎鸠，在河之洲。窈窕淑女，君子好逑。\n参差荇菜，左右流之。窈窕淑女，寤寐求之。\n求之不得，寤寐思服。悠哉悠哉，辗转反侧。\n参差荇菜，左右采之。窈窕淑女，琴瑟友之。\n参差荇菜，左右芼之。窈窕淑女，钟鼓乐之。","tags":["诗经","爱情","国风","高中必背"]},{"id":"xianqin_002","title":"蒹葭","author":"《诗经》","dynasty":"先秦","dynastyCode":"xianqin","content":"蒹葭苍苍，白露为霜。所谓伊人，在水一方。\n溯洄从之，道阻且长。溯游从之，宛在水中央。\n蒹葭萋萋，白露未晞。所谓伊人，在水之湄。\n溯洄从之，道阻且跻。溯游从之，宛在水中坻。\n蒹葭采采，白露未已。所谓伊人，在水之涘。\n溯洄从之，道阻且右。溯游从之，宛在水中沚。","tags":["诗经","爱情","国风","高中必背"]},{"id":"xianqin_003","title":"离骚（节选）","author":"屈原","dynasty":"先秦","dynastyCode":"xianqin","content":"长太息以掩涕兮，哀民生之多艰。\n余虽好修姱以鞿羁兮，謇朝谇而夕替。\n既替余以蕙纕兮，又申之以揽茝。\n亦余心之所善兮，虽九死其犹未悔。\n怨灵修之浩荡兮，终不察夫民心。\n众女嫉余之蛾眉兮，谣诼谓余以善淫。\n固时俗之工巧兮，偭规矩而改错。\n背绳墨以追曲兮，竞周容以为度。\n忳郁邑余侘傺兮，吾独穷困乎此时也。\n宁溘死以流亡兮，余不忍为此态也。\n鸷鸟之不群兮，自前世而固然。\n何方圜之能周兮，夫孰异道而相安？\n屈心而抑志兮，忍尤而攘诟。\n伏清白以死直兮，固前圣之所厚。","tags":["楚辞","爱国","高中必背","名篇"]},{"id":"xianqin_004","title":"氓","author":"《诗经》","dynasty":"先秦","dynastyCode":"xianqin","content":"氓之蚩蚩，抱布贸丝。匪来贸丝，来即我谋。\n送子涉淇，至于顿丘。匪我愆期，子无良媒。\n将子无怒，秋以为期。\n乘彼垝垣，以望复关。不见复关，泣涕涟涟。\n既见复关，载笑载言。尔卜尔筮，体无咎言。\n以尔车来，以我贿迁。\n桑之未落，其叶沃若。于嗟鸠兮，无食桑葚！\n于嗟女兮，无与士耽！士之耽兮，犹可说也。\n女之耽兮，不可说也。\n桑之落矣，其黄而陨。自我徂尔，三岁食贫。\n淇水汤汤，渐车帷裳。女也不爽，士贰其行。\n士也罔极，二三其德。\n三岁为妇，靡室劳矣。夙兴夜寐，靡有朝矣。\n言既遂矣，至于暴矣。兄弟不知，咥其笑矣。\n静言思之，躬自悼矣。\n及尔偕老，老使我怨。淇则有岸，隰则有泮。\n总角之宴，言笑晏晏。信誓旦旦，不思其反。\n反是不思，亦已焉哉！","tags":["诗经","叙事","高中必背","弃妇"]},{"id":"xianqin_005","title":"采薇","author":"《诗经》","dynasty":"先秦","dynastyCode":"xianqin","content":"采薇采薇，薇亦作止。曰归曰归，岁亦莫止。\n靡室靡家，猃狁之故。不遑启居，猃狁之故。\n采薇采薇，薇亦柔止。曰归曰归，心亦忧止。\n忧心烈烈，载饥载渴。我戍未定，靡使归聘。\n采薇采薇，薇亦刚止。曰归曰归，岁亦阳止。\n王事靡盬，不遑启处。忧心孔疚，我行不来。\n彼尔维何？维常之华。彼路斯何？君子之车。\n戎车既驾，四牡业业。岂敢定居？一月三捷。\n驾彼四牡，四牡骙骙。君子所依，小人所腓。\n四牡翼翼，象弭鱼服。岂不日戒？猃狁孔棘。\n昔我往矣，杨柳依依。今我来思，雨雪霏霏。\n行道迟迟，载渴载饥。我心伤悲，莫知我哀！","tags":["诗经","边塞","高中必背","思乡"]},{"id":"xianqin_006","title":"国殇","author":"屈原","dynasty":"先秦","dynastyCode":"xianqin","content":"操吴戈兮被犀甲，车错毂兮短兵接。\n旌蔽日兮敌若云，矢交坠兮士争先。\n凌余阵兮躐余行，左骖殪兮右刃伤。\n霾两轮兮絷四马，援玉枹兮击鸣鼓。\n天时怼兮威灵怒，严杀尽兮弃原野。\n出不入兮往不反，平原忽兮路超远。\n带长剑兮挟秦弓，首身离兮心不惩。\n诚既勇兮又以武，终刚强兮不可凌。\n身既死兮神以灵，魂魄毅兮为鬼雄。","tags":["楚辞","爱国","悼亡","高中必背"]},{"id":"xianqin_007","title":"湘夫人","author":"屈原","dynasty":"先秦","dynastyCode":"xianqin","content":"帝子降兮北渚，目眇眇兮愁予。\n袅袅兮秋风，洞庭波兮木叶下。\n登白薠兮骋望，与佳期兮夕张。\n鸟何萃兮蘋中，罾何为兮木上？\n沅有芷兮澧有兰，思公子兮未敢言。\n荒忽兮远望，观流水兮潺湲。\n麋何食兮庭中？蛟何为兮水裔？\n朝驰余马兮江皋，夕济兮西澨。\n闻佳人兮召予，将腾驾兮偕逝。\n筑室兮水中，葺之兮荷盖。\n荪壁兮紫坛，播芳椒兮成堂。\n桂栋兮兰橑，辛夷楣兮药房。\n罔薜荔兮为帷，擗蕙櫋兮既张。\n白玉兮为镇，疏石兰兮为芳。\n芷葺兮荷屋，缭之兮杜衡。\n合百草兮实庭，建芳馨兮庑门。\n九嶷缤兮并迎，灵之来兮如云。\n捐余袂兮江中，遗余褋兮澧浦。\n搴汀洲兮杜若，将以遗兮远者。\n时不可兮骤得，聊逍遥兮容与。","tags":["楚辞","爱情","神话","名篇"]},{"id":"xianqin_008","title":"子衿","author":"《诗经》","dynasty":"先秦","dynastyCode":"xianqin","content":"青青子衿，悠悠我心。纵我不往，子宁不嗣音？\n青青子佩，悠悠我思。纵我不往，子宁不来？\n挑兮达兮，在城阙兮。一日不见，如三月兮。","tags":["诗经","爱情","名篇"]},{"id":"xianqin_009","title":"桃夭","author":"《诗经》","dynasty":"先秦","dynastyCode":"xianqin","content":"桃之夭夭，灼灼其华。之子于归，宜其室家。\n桃之夭夭，有蕡其实。之子于归，宜其家室。\n桃之夭夭，其叶蓁蓁。之子于归，宜其家人。","tags":["诗经","婚嫁","名篇"]},{"id":"xianqin_010","title":"无衣","author":"《诗经》","dynasty":"先秦","dynastyCode":"xianqin","content":"岂曰无衣？与子同袍。王于兴师，修我戈矛，与子同仇！岂曰无衣？与子同泽。王于兴师，修我矛戟，与子偕作！岂曰无衣？与子同裳。王于兴师，修我甲兵，与子偕行！","tags":["诗经","秦风","爱国","名篇"]},{"id":"xianqin_011","title":"击壤歌","author":"先秦民歌","dynasty":"先秦","dynastyCode":"xianqin","content":"日出而作，日入而息。凿井而饮，耕田而食。帝力于我何有哉！","tags":["民歌","隐逸","名篇"]},{"id":"xianqin_012","title":"九歌·山鬼","author":"屈原","dynasty":"先秦","dynastyCode":"xianqin","content":"若有人兮山之阿，被薜荔兮带女萝。既含睇兮又宜笑，子慕予兮善窈窕。乘赤豹兮从文狸，辛夷车兮结桂旗。被石兰兮带杜衡，折芳馨兮遗所思。余处幽篁兮终不见天，路险难兮独后来。表独立兮山之上，云容容兮而在下。杳冥冥兮羌昼晦，东风飘兮神灵雨。留灵修兮憺忘归，岁既晏兮孰华予？","tags":["楚辞","九歌","神话","名篇"]},{"id":"yuan_001","title":"天净沙·秋思","author":"马致远","dynasty":"元","dynastyCode":"yuan","content":"枯藤老树昏鸦，\n小桥流水人家，\n古道西风瘦马。\n夕阳西下，\n断肠人在天涯。","tags":["元曲","小令","秋思之祖","初中必背","马致远"]},{"id":"yuan_002","title":"山坡羊·潼关怀古","author":"张养浩","dynasty":"元","dynastyCode":"yuan","content":"峰峦如聚，波涛如怒，\n山河表里潼关路。\n望西都，意踌躇。\n伤心秦汉经行处，宫阙万间都做了土。\n兴，百姓苦；亡，百姓苦。","tags":["元曲","怀古","名篇","初中必背","张养浩"]},{"id":"yuan_003","title":"窦娥冤（节选）","author":"关汉卿","dynasty":"元","dynastyCode":"yuan","content":"【滚绣球】有日月朝暮悬，有鬼神掌着生死权。\n天地也！只合把清浊分辨，可怎生糊突了盗跖、颜渊？\n为善的受贫穷更命短，造恶的享富贵又寿延。\n天地也！做得个怕硬欺软，却原来也这般顺水推船！\n地也，你不分好歹何为地？\n天也，你错勘贤愚枉做天！\n哎，只落得两泪涟涟。","tags":["元杂剧","悲剧","名篇","高中必背","关汉卿"]},{"id":"yuan_004","title":"寿阳曲·远浦帆归","author":"马致远","dynasty":"元","dynastyCode":"yuan","content":"夕阳下，酒旆闲，\n两三航未曾着岸。\n落花水香茅舍晚，\n断桥头卖鱼人散。","tags":["元曲","小令","写景","马致远"]},{"id":"yuan_005","title":"长亭送别（节选）","author":"王实甫","dynasty":"元","dynastyCode":"yuan","content":"【正宫·端正好】碧云天，黄花地，西风紧，北雁南飞。晓来谁染霜林醉？总是离人泪。","tags":["元杂剧","西厢记","送别","高中必背","王实甫"]},{"id":"yuan_006","title":"山坡羊·骊山怀古","author":"张养浩","dynasty":"元","dynastyCode":"yuan","content":"骊山四顾，阿房一炬，当时奢侈今何处？只见草萧疏，水萦纡。至今遗恨迷烟树。列国周齐秦汉楚，赢，都变做了土；输，都变做了土。","tags":["元曲","怀古","初中必背","张养浩"]},{"id":"yuan_007","title":"天净沙·秋","author":"白朴","dynasty":"元","dynastyCode":"yuan","content":"孤村落日残霞，轻烟老树寒鸦，一点飞鸿影下。青山绿水，白草红叶黄花。","tags":["元曲","小令","写景","初中必背","白朴"]},{"id":"yuan_008","title":"四块玉·闲适","author":"关汉卿","dynasty":"元","dynastyCode":"yuan","content":"旧酒投，新醅泼，老瓦盆边笑呵呵，共山僧野叟闲吟和。他出一对鸡，我出一个鹅，闲快活！","tags":["元曲","小令","闲适","关汉卿"]},{"id":"yuan_009","title":"凭阑人·寄征衣","author":"姚燧","dynasty":"元","dynastyCode":"yuan","content":"欲寄君衣君不还，不寄君衣君又寒。寄与不寄间，妾身千万难。","tags":["元曲","小令","闺怨","经典","姚燧"]},{"id":"yuan_010","title":"沉醉东风·秋景","author":"卢挚","dynasty":"元","dynastyCode":"yuan","content":"挂绝壁松枯倒倚，落残霞孤鹜齐飞。四围不尽山，一望无穷水。散西风满天秋意。夜静云帆月影低，载我在潇湘画里。","tags":["元曲","小令","写景","经典","卢挚"]}]
